window.VB_DATA={"categories":["Mand","Tact","Listener","VP/MTS","Play","Social","Imitation","Echoic","Vocal","LRFFC","Intraverbal","Classroom","Linguistics","Reading","Writing","Math"],"categoryLabels":{"Mand":{"en":"Mand","ar":"الطلب"},"Tact":{"en":"Tact","ar":"التسمية"},"Listener":{"en":"Listener Responding","ar":"استجابة المستمع"},"VP/MTS":{"en":"VP/MTS","ar":"الإدراك البصري والمطابقة"},"Play":{"en":"Independent Play","ar":"اللعب المستقل"},"Social":{"en":"Social Behavior","ar":"السلوك الاجتماعي"},"Imitation":{"en":"Motor Imitation","ar":"التقليد الحركي"},"Echoic":{"en":"Echoic","ar":"الترديد"},"Vocal":{"en":"Spontaneous Vocal","ar":"الأصوات العفوية"},"LRFFC":{"en":"LRFFC","ar":"استجابة المستمع بالوظيفة والميزة والفئة"},"Intraverbal":{"en":"Intraverbal","ar":"التواصل اللفظي الداخلي"},"Classroom":{"en":"Classroom Routines","ar":"روتين الفصل"},"Linguistics":{"en":"Linguistic Structure","ar":"البناء اللغوي"},"Reading":{"en":"Reading","ar":"القراءة"},"Writing":{"en":"Writing","ar":"الكتابة"},"Math":{"en":"Math","ar":"الحساب"}},"levelDescriptions":{"1":{"en":"Level 1 of the VB-MAPP Milestone Assessment is designed for children developmentally between 0 and 18 months of age.","ar":"المستوى 1 من تقييم معالم VB-MAPP مصمم للأطفال الذين تتراوح أعمارهم بين 0 و 18 شهرًا."},"2":{"en":"Level 2 of the VB-MAPP Milestone Assessment is designed for children developmentally between 18 and 30 months of age.","ar":"المستوى 2 من تقييم معالم VB-MAPP مصمم للأطفال الذين تتراوح أعمارهم بين 18 و 30 شهرًا."},"3":{"en":"Level 3 of the VB-MAPP Milestone Assessment is designed for children developmentally between 30 and 48 months of age. This level consists of 13 skill areas, including three new academic sections: Reading, Writing, and Math.","ar":"المستوى 3 من تقييم معالم VB-MAPP مصمم للأطفال الذين تتراوح أعمارهم بين 30 و 48 شهرًا. يتكون هذا المستوى من 13 مجال مهارة، بما في ذلك ثلاثة أقسام أكاديمية جديدة: القراءة والكتابة والرياضيات."}},"milestones":[{"id":"m1-1","level":1,"category":"Mand","milestone":1,"text":{"en":"Emits 2 words, signs, or PECS with echoic, imitative, or pointing prompts","ar":"يصدر كلمتين أو إشارتين أو صور بمساعدة لفظية أو تقليدية أو إشارية"},"objective":{"en":"To determine how a child makes their needs known and if they can move from prompted to spontaneous requests.","ar":"لتحديد كيفية تعبير الطفل عن احتياجاته وما إذا كان بإمكانه الانتقال من الطلبات الموجهة إلى الطلبات العفوية."},"application":{"en":"Gather reinforcing items/actions. Provide a prompt (e.g., \"say cookie\") when the child wants the item.","ar":"اجمع الأشياء/الأفعال المعززة. قدم مساعدة (مثلاً: \"قل كوكيز\") عندما يريد الطفل الشيء."},"scoring":{"en":"1 point for 2 mands with prompts; 1/2 point for 1 mand. No points if physical prompts are used.","ar":"درجة واحدة لطلبين بمساعدة؛ نصف درجة لطلب واحد. لا يتم احتساب درجات إذا تم استخدام المساعدة الجسدية."}},{"id":"m1-2","level":1,"category":"Mand","milestone":2,"text":{"en":"Emits 4 different mands without prompts (except \"What do you want?\"); item may be present","ar":"يصدر 4 طلبات مختلفة بدون مساعدة (باستثناء \"ماذا تريد؟\")؛ قد يكون الشيء موجوداً"},"objective":{"en":"To determine how a child makes their needs known and if they can move from prompted to spontaneous requests.","ar":"لتحديد كيفية تعبير الطفل عن احتياجاته وما إذا كان بإمكانه الانتقال من الطلبات الموجهة إلى الطلبات العفوية."},"application":{"en":"Determine if the child mands without the adult saying the target word.","ar":"حدد ما إذا كان الطفل يطلب دون أن يقول الشخص البالغ الكلمة المستهدفة."},"scoring":{"en":"1 point for 4 different unprompted mands; 1/2 point for 3 mands.","ar":"درجة واحدة لـ 4 طلبات مختلفة غير موجهة؛ نصف درجة لـ 3 طلبات."}},{"id":"m1-3","level":1,"category":"Mand","milestone":3,"text":{"en":"Generalizes 6 mands across 2 people, 2 settings, and 2 different examples of a reinforcer","ar":"يعمم 6 طلبات عبر شخصين وبيئتين ومثالين مختلفين للمعزز"},"objective":{"en":"To determine how a child makes their needs known and if they can move from prompted to spontaneous requests.","ar":"لتحديد كيفية تعبير الطفل عن احتياجاته وما إذا كان بإمكانه الانتقال من الطلبات الموجهة إلى الطلبات العفوية."},"application":{"en":"Test if a mand (e.g., \"bubbles\") occurs with different people, in different rooms, and with different versions of the item.","ar":"اختبر ما إذا كان الطلب (مثلاً: \"فقاعات\") يحدث مع أشخاص مختلفين، وفي غرف مختلفة، ومع نسخ مختلفة من الشيء."},"scoring":{"en":"1 point for 6 generalized mands; 1/2 point for 3.","ar":"درجة واحدة لـ 6 طلبات معممة؛ نصف درجة لـ 3 طلبات."}},{"id":"m1-4","level":1,"category":"Mand","milestone":4,"text":{"en":"Spontaneously emits 5 mands; desired item can be present","ar":"يصدر 5 طلبات بشكل عفوي؛ يمكن أن يكون الشيء المطلوب موجوداً"},"objective":{"en":"To determine how a child makes their needs known and if they can move from prompted to spontaneous requests.","ar":"لتحديد كيفية تعبير الطفل عن احتياجاته وما إذا كان بإمكانه الانتقال من الطلبات الموجهة إلى الطلبات العفوية."},"application":{"en":"Observe the child in a natural environment. The request must be initiated by the child's motivation (MO) without an adult prompt.","ar":"لاحظ الطفل في بيئة طبيعية. يجب أن يبدأ الطلب بدافع من الطفل (MO) دون مساعدة من شخص بالغ."},"scoring":{"en":"1 point for 5 spontaneous mands (at least 2 different types); 1/2 point for 5 mands that are all the same word.","ar":"درجة واحدة لـ 5 طلبات عفوية (على الأقل نوعان مختلفان)؛ نصف درجة لـ 5 طلبات كلها نفس الكلمة."}},{"id":"m1-5","level":1,"category":"Mand","milestone":5,"text":{"en":"Emits 10 different mands without prompts (except \"What do you want?\"); item can be present","ar":"يصدر 10 طلبات مختلفة بدون مساعدة (باستثناء \"ماذا تريد؟\")؛ يمكن أن يكون الشيء موجوداً"},"objective":{"en":"To determine how a child makes their needs known and if they can move from prompted to spontaneous requests.","ar":"لتحديد كيفية تعبير الطفل عن احتياجاته وما إذا كان بإمكانه الانتقال من الطلبات الموجهة إلى الطلبات العفوية."},"application":{"en":"Gather various reinforcers and check for 10 unique requests without echoic or imitative prompts.","ar":"اجمع معززات متنوعة وتحقق من وجود 10 طلبات فريدة دون مساعدة ترديدية أو تقليدية."},"scoring":{"en":"1 point for 10 different mands; 1/2 point for 8.","ar":"درجة واحدة لـ 10 طلبات مختلفة؛ نصف درجة لـ 8 طلبات."}},{"id":"t1-1","level":1,"category":"Tact","milestone":1,"text":{"en":"Tacts 2 items (e.g., people, pets, or favorite objects)","ar":"يسمي شيئين (مثل الأشخاص أو الحيوانات الأليفة أو الأشياء المفضلة)"},"objective":{"en":"To determine if a nonverbal stimulus (like an object) evokes a name without echoic prompts.","ar":"لتحديد ما إذا كان المثير غير اللفظي (مثل الشيء) يستدعي اسماً دون مساعدة ترديدية."},"application":{"en":"Present a familiar item and ask \"What's that?\".","ar":"قدم شيئاً مألوفاً واسأل \"ما هذا؟\"."},"scoring":{"en":"1 point for 2 items; 1/2 point for 1. No credit if the child calls everything the same name.","ar":"درجة واحدة لشيئين؛ نصف درجة لشيء واحد. لا يتم احتساب درجة إذا كان الطفل يسمي كل شيء بنفس الاسم."}},{"id":"t1-2","level":1,"category":"Tact","milestone":2,"text":{"en":"Tacts any 4 items","ar":"يسمي أي 4 أشياء"},"objective":{"en":"To determine if a nonverbal stimulus (like an object) evokes a name without echoic prompts.","ar":"لتحديد ما إذا كان المثير غير اللفظي (مثل الشيء) يستدعي اسماً دون مساعدة ترديدية."},"application":{"en":"Use common items/reinforcers in the child's natural environment.","ar":"استخدم الأشياء/المعززات الشائعة في البيئة الطبيعية للطفل."},"scoring":{"en":"1 point for 4 items; 1/2 point for 3.","ar":"درجة واحدة لـ 4 أشياء؛ نصف درجة لـ 3 أشياء."}},{"id":"t1-3","level":1,"category":"Tact","milestone":3,"text":{"en":"Tacts 6 non-reinforcing items (e.g., shoe, hat, spoon)","ar":"يسمي 6 أشياء غير معززة (مثل الحذاء، القبعة، الملعقة)"},"objective":{"en":"To determine if a nonverbal stimulus (like an object) evokes a name without echoic prompts.","ar":"لتحديد ما إذا كان المثير غير اللفظي (مثل الشيء) يستدعي اسماً دون مساعدة ترديدية."},"application":{"en":"Ensure the child is labeling items they do not currently want to ensure the response is a tact, not a mand.","ar":"تأكد من أن الطفل يسمي أشياء لا يريدها حالياً لضمان أن الاستجابة هي تسمية وليست طلباً."},"scoring":{"en":"1 point for 6 items; 1/2 point for 5.","ar":"درجة واحدة لـ 6 أشياء؛ نصف درجة لـ 5 أشياء."}},{"id":"t1-4","level":1,"category":"Tact","milestone":4,"text":{"en":"Spontaneously tacts 2 different items","ar":"يسمي شيئين مختلفين بشكل عفوي"},"objective":{"en":"To determine if a nonverbal stimulus (like an object) evokes a name without echoic prompts.","ar":"لتحديد ما إذا كان المثير غير اللفظي (مثل الشيء) يستدعي اسماً دون مساعدة ترديدية."},"application":{"en":"Observe if the child labels something because it is \"fun\" to say, without being asked.","ar":"لاحظ ما إذا كان الطفل يسمي شيئاً لأنه من \"الممتع\" قوله، دون أن يُطلب منه ذلك."},"scoring":{"en":"1 point for 2 spontaneous tacts; 1/2 point for 1.","ar":"درجة واحدة لتسميتين عفوية؛ نصف درجة لتسمية واحدة."}},{"id":"t1-5","level":1,"category":"Tact","milestone":5,"text":{"en":"Tacts 10 items (common objects, body parts, or pictures)","ar":"يسمي 10 أشياء (أشياء شائعة، أجزاء الجسم، أو صور)"},"objective":{"en":"To determine if a nonverbal stimulus (like an object) evokes a name without echoic prompts.","ar":"لتحديد ما إذا كان المثير غير اللفظي (مثل الشيء) يستدعي اسماً دون مساعدة ترديدية."},"application":{"en":"Test for 10 items using the prompt \"What's that?\".","ar":"اختبر 10 أشياء باستخدام المساعدة \"ما هذا؟\"."},"scoring":{"en":"1 point for 10 items; 1/2 point for 8.","ar":"درجة واحدة لـ 10 أشياء؛ نصف درجة لـ 8 أشياء."}},{"id":"l1-1","level":1,"category":"Listener","milestone":1,"text":{"en":"Attends to a speaker’s voice by making eye contact 5 times","ar":"ينتبه لصوت المتحدث من خلال التواصل البصري 5 مرات"},"objective":{"en":"To identify the child’s ability to understand and respond to the words of others.","ar":"لتحديد قدرة الطفل على فهم كلمات الآخرين والاستجابة لها."},"application":{"en":"Observe if the child looks at the speaker’s eyes when they talk or sing.","ar":"لاحظ ما إذا كان الطفل ينظر إلى عيني المتحدث عندما يتحدث أو يغني."},"scoring":{"en":"1 point for 5 times; 1/2 point for 2 times.","ar":"درجة واحدة لـ 5 مرات؛ نصف درجة لمرتين."}},{"id":"l1-2","level":1,"category":"Listener","milestone":2,"text":{"en":"Responds to hearing their own name 5 times","ar":"يستجيب لسماع اسمه 5 مرات"},"objective":{"en":"To identify the child’s ability to understand and respond to the words of others.","ar":"لتحديد قدرة الطفل على فهم كلمات الآخرين والاستجابة لها."},"application":{"en":"While the child is looking away, call their name and see if they turn/look.","ar":"بينما ينظر الطفل بعيداً، نادِ اسمه وانظر ما إذا كان يلتفت/ينظر."},"scoring":{"en":"1 point for 5 separate trials. No 1/2 point for this skill.","ar":"درجة واحدة لـ 5 محاولات منفصلة. لا توجد نصف درجة لهذه المهارة."}},{"id":"l1-3","level":1,"category":"Listener","milestone":3,"text":{"en":"Looks at, touches, or points to a family member or pet in an array of 2 for 5 items","ar":"ينظر أو يلمس أو يشير إلى أحد أفراد الأسرة أو حيوان أليف في مجموعة من 2 لـ 5 عناصر"},"objective":{"en":"To identify the child’s ability to understand and respond to the words of others.","ar":"لتحديد قدرة الطفل على فهم كلمات الآخرين والاستجابة لها."},"application":{"en":"Place two choices (e.g., Mom and a stranger, or two toys) and ask \"Where's [Name]?\".","ar":"ضع خيارين (مثلاً: الأم وشخص غريب، أو لعبتين) واسأل \"أين [الاسم]؟\"."},"scoring":{"en":"1 point for 5 items; 1/2 point for 2.","ar":"درجة واحدة لـ 5 عناصر؛ نصف درجة لعنصرين."}},{"id":"l1-4","level":1,"category":"Listener","milestone":4,"text":{"en":"Performs 4 different motor actions on command without a visual prompt","ar":"يؤدي 4 حركات حركية مختلفة بناءً على أمر دون مساعدة بصرية"},"objective":{"en":"To identify the child’s ability to understand and respond to the words of others.","ar":"لتحديد قدرة الطفل على فهم كلمات الآخرين والاستجابة لها."},"application":{"en":"Give a verbal command like \"jump\" or \"clap\" without gesturing or demonstrating.","ar":"أعطِ أمراً لفظياً مثل \"اقفز\" أو \"صفق\" دون إيماءة أو عرض توضيحي."},"scoring":{"en":"1 point for 4 actions (2 times each); 1/2 point for 2 actions.","ar":"درجة واحدة لـ 4 أفعال (مرتين لكل منها)؛ نصف درجة لفعلين."}},{"id":"l1-5","level":1,"category":"Listener","milestone":5,"text":{"en":"Selects the correct item from an array of 4 for 20 different objects/pictures","ar":"يختار الشيء الصحيح من مجموعة من 4 لـ 20 غرضاً/صورة مختلفة"},"objective":{"en":"To identify the child’s ability to understand and respond to the words of others.","ar":"لتحديد قدرة الطفل على فهم كلمات الآخرين والاستجابة لها."},"application":{"en":"Use a messy array and ask the child to \"Touch [item]\".","ar":"استخدم مجموعة فوضوية واسأل الطفل \"المس [الشيء]\"."},"scoring":{"en":"1 point for 20 items (first trial); 1/2 point for 15 items.","ar":"درجة واحدة لـ 20 شيئاً (المحاولة الأولى)؛ نصف درجة لـ 15 شيئاً."}},{"id":"vp1-1","level":1,"category":"VP/MTS","milestone":1,"text":{"en":"Visually tracks moving stimuli for 2 seconds, 5 times","ar":"يتتبع بصرياً المثيرات المتحركة لمدة ثانيتين، 5 مرات"},"objective":{"en":"To assess eye-hand coordination and the ability to visually discriminate between items.","ar":"لتقييم التنسيق بين العين واليد والقدرة على التمييز البصري بين الأشياء."},"application":{"en":"Observe the child watching a pet or a rolling toy move across the room.","ar":"لاحظ الطفل وهو يشاهد حيواناً أليفاً أو لعبة تتدحرج تتحرك عبر الغرفة."},"scoring":{"en":"1 point for 5 times; 1/2 point for 2 times.","ar":"درجة واحدة لـ 5 مرات؛ نصف درجة لمرتين."}},{"id":"vp1-2","level":1,"category":"VP/MTS","milestone":2,"text":{"en":"Grasps small objects with a pincer grasp 5 times","ar":"يمسك الأشياء الصغيرة بقبضة الكماشة 5 مرات"},"objective":{"en":"To assess eye-hand coordination and the ability to visually discriminate between items.","ar":"لتقييم التنسيق بين العين واليد والقدرة على التمييز البصري بين الأشياء."},"application":{"en":"Observe the child picking up small items (e.g., Cheerios, crayons) using their thumb and index finger.","ar":"لاحظ الطفل وهو يلتقط أشياء صغيرة (مثل الحبوب، أقلام التلوين) باستخدام الإبهام والسبابة."},"scoring":{"en":"1 point for 5 successes; 1/2 point if they usually take 2+ attempts.","ar":"درجة واحدة لـ 5 نجاحات؛ نصف درجة إذا كانوا يحتاجون عادةً إلى محاولتين أو أكثر."}},{"id":"vp1-3","level":1,"category":"VP/MTS","milestone":3,"text":{"en":"Visually attends to a toy or book for 30 seconds","ar":"ينتبه بصرياً للعبة أو كتاب لمدة 30 ثانية"},"objective":{"en":"To assess eye-hand coordination and the ability to visually discriminate between items.","ar":"لتقييم التنسيق بين العين واليد والقدرة على التمييز البصري بين الأشياء."},"application":{"en":"Observe sustained attention to an item that is not a self-stimulatory object.","ar":"لاحظ الانتباه المستمر لشيء ليس غرضاً للتحفيز الذاتي."},"scoring":{"en":"1 point for 30 seconds; 1/2 point for 15 seconds.","ar":"درجة واحدة لـ 30 ثانية؛ نصف درجة لـ 15 ثانية."}},{"id":"vp1-4","level":1,"category":"VP/MTS","milestone":4,"text":{"en":"Places 3 items in a container, stacks 3 blocks, or places 3 rings on a peg","ar":"يضع 3 عناصر في حاوية، أو يرص 3 مكعبات، أو يضع 3 حلقات على وتد"},"objective":{"en":"To assess eye-hand coordination and the ability to visually discriminate between items.","ar":"لتقييم التنسيق بين العين واليد والقدرة على التمييز البصري بين الأشياء."},"application":{"en":"Test fine motor control through activities like block stacking or ring-stacking.","ar":"اختبر التحكم الحركي الدقيق من خلال أنشطة مثل رص المكعبات أو رص الحلقات."},"scoring":{"en":"1 point for completing 2 different activities; 1/2 point for 1 activity.","ar":"درجة واحدة لإكمال نشاطين مختلفين؛ نصف درجة لنشاط واحد."}},{"id":"vp1-5","level":1,"category":"VP/MTS","milestone":5,"text":{"en":"Matches any 10 identical items (e.g., inset puzzles, toys, or pictures)","ar":"يطابق أي 10 أشياء متماثلة (مثل الألغاز، الألعاب، أو الصور)"},"objective":{"en":"To assess eye-hand coordination and the ability to visually discriminate between items.","ar":"لتقييم التنسيق بين العين واليد والقدرة على التمييز البصري بين الأشياء."},"application":{"en":"Show a sample (e.g., a spoon) and ask the child to find the match in a small group.","ar":"اعرض عينة (مثلاً: ملعقة) واطلب من الطفل العثور على المطابق في مجموعة صغيرة."},"scoring":{"en":"1 point for 10 items; 1/2 point for 5.","ar":"درجة واحدة لـ 10 أشياء؛ نصف درجة لـ 5 أشياء."}},{"id":"p1-1","level":1,"category":"Play","milestone":1,"text":{"en":"Manipulates and explores objects for 1 minute","ar":"يستكشف الأشياء لمدة دقيقة واحدة"},"objective":{"en":"To determine if the child engages in behavior that is automatically reinforcing (the behavior itself is \"fun\") without adult prompts.","ar":"لتحديد ما إذا كان الطفل ينخرط في سلوك يعزز نفسه تلقائياً (السلوك نفسه \"ممتع\") دون توجيهات من الكبار."},"application":{"en":"Observe the child turning a toy over, pressing buttons, or exploring textures.","ar":"لاحظ الطفل وهو يقلب لعبة، أو يضغط على الأزرار، أو يستكشف الأنسجة."},"scoring":{"en":"1 point for 1 minute; 1/2 point for 30 seconds.","ar":"درجة واحدة لدقيقة واحدة؛ نصف درجة لـ 30 ثانية."}},{"id":"p1-2","level":1,"category":"Play","milestone":2,"text":{"en":"Shows variation in play by interacting with 5 different items","ar":"يظهر تنوعاً في اللعب من خلال التفاعل مع 5 أشياء مختلفة"},"objective":{"en":"To determine if the child engages in behavior that is automatically reinforcing (the behavior itself is \"fun\") without adult prompts.","ar":"لتحديد ما إذا كان الطفل ينخرط في سلوك يعزز نفسه تلقائياً (السلوك نفسه \"ممتع\") دون توجيهات من الكبار."},"application":{"en":"Observe the child moving between different toys (e.g., from a block to a ball).","ar":"لاحظ الطفل وهو ينتقل بين ألعاب مختلفة (مثلاً: من مكعب إلى كرة)."},"scoring":{"en":"1 point for 5 different items; 1/2 point for 3.","ar":"درجة واحدة لـ 5 أشياء مختلفة؛ نصف درجة لـ 3 أشياء."}},{"id":"p1-3","level":1,"category":"Play","milestone":3,"text":{"en":"Generalizes play by exploring a novel environment for 2 minutes","ar":"يعمم اللعب من خلال استكشاف بيئة جديدة لمدة دقيقتين"},"objective":{"en":"To determine if the child engages in behavior that is automatically reinforcing (the behavior itself is \"fun\") without adult prompts.","ar":"لتحديد ما إذا كان الطفل ينخرط في سلوك يعزز نفسه تلقائياً (السلوك نفسه \"ممتع\") دون توجيهات من الكبار."},"application":{"en":"Take the child to a new playroom or area and observe if they explore and play.","ar":"خذ الطفل إلى غرفة ألعاب أو منطقة جديدة ولاحظ ما إذا كان يستكشف ويلعب."},"scoring":{"en":"1 point for 2 minutes; 1/2 point for 1 minute.","ar":"درجة واحدة لدقيقتين؛ نصف درجة لدقيقة واحدة."}},{"id":"p1-4","level":1,"category":"Play","milestone":4,"text":{"en":"Independently engages in movement play for 2 minutes (e.g., swinging, jumping)","ar":"ينخرط بشكل مستقل في اللعب الحركي لمدة دقيقتين (مثل الأرجحة، القفز)"},"objective":{"en":"To determine if the child engages in behavior that is automatically reinforcing (the behavior itself is \"fun\") without adult prompts.","ar":"لتحديد ما إذا كان الطفل ينخرط في سلوك يعزز نفسه تلقائياً (السلوك نفسه \"ممتع\") دون توجيهات من الكبار."},"application":{"en":"Observe if the child enjoys physical activities like sliding or climbing without help.","ar":"لاحظ ما إذا كان الطفل يستمتع بالأنشطة البدنية مثل الانزلاق أو التسلق دون مساعدة."},"scoring":{"en":"1 point for 2 minutes; 1/2 point for 1 minute.","ar":"درجة واحدة لدقيقتين؛ نصف درجة لدقيقة واحدة."}},{"id":"p1-5","level":1,"category":"Play","milestone":5,"text":{"en":"Engages in cause-and-effect play for 2 minutes (e.g., dumping containers)","ar":"ينخرط في لعب السبب والنتيجة لمدة دقيقتين (مثل تفريغ الحاويات)"},"objective":{"en":"To determine if the child engages in behavior that is automatically reinforcing (the behavior itself is \"fun\") without adult prompts.","ar":"لتحديد ما إذا كان الطفل ينخرط في سلوك يعزز نفسه تلقائياً (السلوك نفسه \"ممتع\") دون توجيهات من الكبار."},"application":{"en":"Observe activities like pushing buttons for sound or knocking over blocks.","ar":"لاحظ أنشطة مثل الضغط على أزرار للصوت أو إسقاط المكعبات."},"scoring":{"en":"1 point for 2 minutes; 1/2 point for 1 minute.","ar":"درجة واحدة لدقيقتين؛ نصف درجة لدقيقة واحدة."}},{"id":"s1-1","level":1,"category":"Social","milestone":1,"text":{"en":"Makes eye contact as a type of mand 5 times","ar":"يقوم بالتواصل البصري كنوع من الطلب 5 مرات"},"objective":{"en":"To determine if the child uses eye contact to request social interaction.","ar":"تحديد ما إذا كان الطفل يستخدم التواصل البصري لطلب التفاعل الاجتماعي."},"application":{"en":"Observe the child when an adult enters the room or approaches them; no specific materials are required.","ar":"لاحظ الطفل عندما يدخل شخص بالغ الغرفة أو يقترب منه؛ لا توجد مواد محددة مطلوبة."},"scoring":{"en":"1 point for 5 times; 1/2 point for 2 times.","ar":"درجة واحدة لـ 5 مرات؛ نصف درجة لمرتين."}},{"id":"s1-2","level":1,"category":"Social","milestone":2,"text":{"en":"Indicates that he wants to be held or physically played with 2 times","ar":"يشير إلى أنه يريد أن يُحمل أو يُلعب معه جسدياً مرتين"},"objective":{"en":"To determine if physical contact with familiar adults functions as reinforcement for the child.","ar":"تحديد ما إذا كان الاتصال الجسدي مع البالغين المألوفين يعمل كمعزز للطفل."},"application":{"en":"Observe if the child approaches an adult, reaches out their arms, or climbs into a lap for tickles or hugs.","ar":"لاحظ ما إذا كان الطفل يقترب من شخص بالغ، أو يمد ذراعيه، أو يتسلق إلى حضن للدغدغة أو العناق."},"scoring":{"en":"1 point for 2 times; 1/2 point for 1 time.","ar":"درجة واحدة لمرتين؛ نصف درجة لمرة واحدة."}},{"id":"s1-3","level":1,"category":"Social","milestone":3,"text":{"en":"Spontaneously makes eye contact with other children 5 times","ar":"يقوم بالتواصل البصري مع الأطفال الآخرين بشكل عفوي 5 مرات"},"objective":{"en":"To see if peers act as discriminative stimuli for attending to them.","ar":"لمعرفة ما إذا كان الأقران يعملون كمثيرات تمييزية للانتباه إليهم."},"application":{"en":"Observe the child in the presence of peers.","ar":"لاحظ الطفل في وجود الأقران."},"scoring":{"en":"1 point for 5 times; 1/2 point for 2 times.","ar":"درجة واحدة لـ 5 مرات؛ نصف درجة لمرتين."}},{"id":"s1-4","level":1,"category":"Social","milestone":4,"text":{"en":"Spontaneously engages in parallel play near other children for a total of 2 minutes","ar":"ينخرط بشكل عفوي في اللعب الموازي بالقرب من الأطفال الآخرين لمدة دقيقتين إجمالاً"},"objective":{"en":"To determine if a child will stand or sit by other children without adult prompts.","ar":"تحديد ما إذا كان الطفل سيقف أو يجلس بجانب الأطفال الآخرين دون توجيهات من الكبار."},"application":{"en":"Observe the child near common group items like a sandbox or water table.","ar":"لاحظ الطفل بالقرب من عناصر المجموعة الشائعة مثل صندوق الرمل أو طاولة الماء."},"scoring":{"en":"1 point for 2 minutes; 1/2 point for 1 minute.","ar":"درجة واحدة لدقيقتين؛ نصف درجة لدقيقة واحدة."}},{"id":"s1-5","level":1,"category":"Social","milestone":5,"text":{"en":"Spontaneously follows peers or imitates their motor behavior 2 times","ar":"يتبع الأقران بشكل عفوي أو يقلد سلوكهم الحركي مرتين"},"objective":{"en":"To determine if a child will imitate peers without adult prompting.","ar":"تحديد ما إذا كان الطفل سيقلد الأقران دون توجيه من الكبار."},"application":{"en":"Observe if the child follows a peer to a new location or copies a peer's action with a toy.","ar":"لاحظ ما إذا كان الطفل يتبع قرينه إلى مكان جديد أو ينسخ حركة قرينه بلعبة."},"scoring":{"en":"1 point for 2 times; 1/2 point for 1 time.","ar":"درجة واحدة لمرتين؛ نصف درجة لمرة واحدة."}},{"id":"i1-1","level":1,"category":"Imitation","milestone":1,"text":{"en":"Imitates 2 gross motor movements when prompted with \"Do this.\"","ar":"يقلد حركتين كبريين عند مساعدته بـ \"افعل هذا\""},"objective":{"en":"To determine if a child can copy the physical movements of others.","ar":"لتحديد ما إذا كان الطفل يستطيع نسخ الحركات البدنية للآخرين."},"application":{"en":"Model a movement (e.g., clapping) and give the verbal prompt.","ar":"قم بتمثيل حركة (مثلاً: التصفيق) وقدم المساعدة اللفظية."},"scoring":{"en":"1 point for 2 movements; 1/2 point for 1. Approximations are accepted.","ar":"درجة واحدة لحركتين؛ نصف درجة لحركة واحدة. التقريبات مقبولة."}},{"id":"i1-2","level":1,"category":"Imitation","milestone":2,"text":{"en":"Imitates 4 gross motor movements","ar":"يقلد 4 حركات كبرى"},"objective":{"en":"To determine if a child can copy the physical movements of others.","ar":"لتحديد ما إذا كان الطفل يستطيع نسخ الحركات البدنية للآخرين."},"application":{"en":"Use actions like stomping feet or raising arms.","ar":"استخدم أفعالاً مثل ضرب القدمين بالأرض أو رفع الذراعين."},"scoring":{"en":"1 point for 4 movements; 1/2 point for 3.","ar":"درجة واحدة لـ 4 حركات؛ نصف درجة لـ 3 حركات."}},{"id":"i1-3","level":1,"category":"Imitation","milestone":3,"text":{"en":"Imitates 8 motor movements, 2 of which involve objects (e.g., shaking a maraca)","ar":"يقلد 8 حركات حركية، 2 منها تتضمن أشياء (مثل هز الماراكا)"},"objective":{"en":"To determine if a child can copy the physical movements of others.","ar":"لتحديد ما إذا كان الطفل يستطيع نسخ الحركات البدنية للآخرين."},"application":{"en":"Test 6 body movements and 2 actions using objects like tapping a table.","ar":"اختبر 6 حركات للجسم وفعلين باستخدام أشياء مثل النقر على الطاولة."},"scoring":{"en":"1 point for 8 total (including 2 with objects); 1/2 point for 6 of any type.","ar":"درجة واحدة لـ 8 إجمالاً (بما في ذلك 2 مع أشياء)؛ نصف درجة لـ 6 من أي نوع."}},{"id":"i1-4","level":1,"category":"Imitation","milestone":4,"text":{"en":"Spontaneously imitates motor behaviors on 5 occasions","ar":"يقلد السلوكيات الحركية بشكل عفوي في 5 مناسبات"},"objective":{"en":"To determine if a child can copy the physical movements of others.","ar":"لتحديد ما إذا كان الطفل يستطيع نسخ الحركات البدنية للآخرين."},"application":{"en":"Observe if the child copies an action (e.g., pushing a car) without a verbal prompt.","ar":"لاحظ ما إذا كان الطفل ينسخ فعلاً (مثلاً: دفع سيارة) دون مساعدة لفظية."},"scoring":{"en":"1 point for 5 occasions (at least 2 different behaviors); 1/2 point for 2 occasions.","ar":"درجة واحدة لـ 5 مناسبات (على الأقل سلوكان مختلفان)؛ نصف درجة لمناسبتين."}},{"id":"i1-5","level":1,"category":"Imitation","milestone":5,"text":{"en":"Imitates 20 motor movements of any type (fine, gross, or with objects)","ar":"يقلد 20 حركة حركية من أي نوع (دقيقة، كبرى، أو مع أشياء)"},"objective":{"en":"To determine if a child can copy the physical movements of others.","ar":"لتحديد ما إذا كان الطفل يستطيع نسخ الحركات البدنية للآخرين."},"application":{"en":"Assess for a generalized imitation repertoire using a variety of actions.","ar":"قم بتقييم حصيلة تقليد معممة باستخدام مجموعة متنوعة من الأفعال."},"scoring":{"en":"1 point for 20 movements; 1/2 point for 15.","ar":"درجة واحدة لـ 20 حركة؛ نصف درجة لـ 15 حركة."}},{"id":"e1-1","level":1,"category":"Echoic","milestone":1,"text":{"en":"Scores at least 2 on the EESA subtest","ar":"يسجل 2 على الأقل في اختبار EESA"},"objective":{"en":"To evaluate the child’s ability to repeat speech models.","ar":"لتقييم قدرة الطفل على تكرار نماذج الكلام."},"application":{"en":"Tasks are scored based on Group 1 of the Early Echoic Skills Assessment.","ar":"يتم تسجيل المهام بناءً على المجموعة 1 من تقييم مهارات الترديد المبكرة (EESA)."},"scoring":{"en":"1 point for score of 2 on EESA.","ar":"درجة واحدة للحصول على 2 في EESA."}},{"id":"e1-2","level":1,"category":"Echoic","milestone":2,"text":{"en":"Scores at least 5 on the EESA subtest","ar":"يسجل 5 على الأقل في اختبار EESA"},"objective":{"en":"To evaluate the child’s ability to repeat speech models.","ar":"لتقييم قدرة الطفل على تكرار نماذج الكلام."},"application":{"en":"Tasks are scored based on Group 1 of the Early Echoic Skills Assessment.","ar":"يتم تسجيل المهام بناءً على المجموعة 1 من تقييم مهارات الترديد المبكرة (EESA)."},"scoring":{"en":"1 point for score of 5 on EESA.","ar":"درجة واحدة للحصول على 5 في EESA."}},{"id":"e1-3","level":1,"category":"Echoic","milestone":3,"text":{"en":"Scores at least 10 on the EESA subtest","ar":"يسجل 10 على الأقل في اختبار EESA"},"objective":{"en":"To evaluate the child’s ability to repeat speech models.","ar":"لتقييم قدرة الطفل على تكرار نماذج الكلام."},"application":{"en":"Tasks are scored based on Group 1 of the Early Echoic Skills Assessment.","ar":"يتم تسجيل المهام بناءً على المجموعة 1 من تقييم مهارات الترديد المبكرة (EESA)."},"scoring":{"en":"1 point for score of 10 on EESA.","ar":"درجة واحدة للحصول على 10 في EESA."}},{"id":"e1-4","level":1,"category":"Echoic","milestone":4,"text":{"en":"Scores at least 15 on the EESA subtest","ar":"يسجل 15 على الأقل في اختبار EESA"},"objective":{"en":"To evaluate the child’s ability to repeat speech models.","ar":"لتقييم قدرة الطفل على تكرار نماذج الكلام."},"application":{"en":"Tasks are scored based on Group 1 of the Early Echoic Skills Assessment.","ar":"يتم تسجيل المهام بناءً على المجموعة 1 من تقييم مهارات الترديد المبكرة (EESA)."},"scoring":{"en":"1 point for score of 15 on EESA.","ar":"درجة واحدة للحصول على 15 في EESA."}},{"id":"e1-5","level":1,"category":"Echoic","milestone":5,"text":{"en":"Scores at least 25 on the EESA subtest (at least 20 from Group 1)","ar":"يسجل 25 على الأقل في اختبار EESA (على الأقل 20 من المجموعة 1)"},"objective":{"en":"To evaluate the child’s ability to repeat speech models.","ar":"لتقييم قدرة الطفل على تكرار نماذج الكلام."},"application":{"en":"Tasks are scored based on Group 1 of the Early Echoic Skills Assessment.","ar":"يتم تسجيل المهام بناءً على المجموعة 1 من تقييم مهارات الترديد المبكرة (EESA)."},"scoring":{"en":"1 point for score of 25 on EESA (at least 20 from Group 1).","ar":"درجة واحدة للحصول على 25 في EESA (على الأقل 20 من المجموعة 1)."}},{"id":"v1-1","level":1,"category":"Vocal","milestone":1,"text":{"en":"Spontaneously emits an average of 5 speech sounds each hour","ar":"يصدر متوسط 5 أصوات كلام كل ساعة بشكل عفوي"},"objective":{"en":"To measure vocal play and babbling, which are essential for developing vocal control.","ar":"لقياس اللعب الصوتي والمناغاة، وهما ضروريان لتطوير التحكم الصوتي."},"application":{"en":"Use time-sampling to record how often the child vocalizes without being prompted.","ar":"استخدم أخذ عينات زمنية لتسجيل عدد المرات التي يصدر فيها الطفل أصواتاً دون أن يُطلب منه ذلك."},"scoring":{"en":"1 point for average of 5 per hour; 1/2 point for average of 2.","ar":"درجة واحدة لمتوسط 5 في الساعة؛ نصف درجة لمتوسط 2."}},{"id":"v1-2","level":1,"category":"Vocal","milestone":2,"text":{"en":"Spontaneously emits 5 different sounds, averaging 10 total sounds per hour","ar":"يصدر 5 أصوات مختلفة بشكل عفوي، بمتوسط 10 أصوات إجمالية في الساعة"},"objective":{"en":"To measure vocal play and babbling, which are essential for developing vocal control.","ar":"لقياس اللعب الصوتي والمناغاة، وهما ضروريان لتطوير التحكم الصوتي."},"application":{"en":"Note the variety of sounds (e.g., \"ba,\" \"ga,\" \"ma\").","ar":"لاحظ تنوع الأصوات (مثل \"با\"، \"غا\"، \"ما\")."},"scoring":{"en":"1 point for 5 sounds/10 total; 1/2 point for 3 sounds/10 total.","ar":"درجة واحدة لـ 5 أصوات/10 إجمالاً؛ نصف درجة لـ 3 أصوات/10 إجمالاً."}},{"id":"v1-3","level":1,"category":"Vocal","milestone":3,"text":{"en":"Spontaneously emits 10 different sounds with varying intonations, averaging 25 total sounds per hour","ar":"يصدر 10 أصوات مختلفة بنبرات متنوعة بشكل عفوي، بمتوسط 25 صوتاً إجمالياً في الساعة"},"objective":{"en":"To measure vocal play and babbling, which are essential for developing vocal control.","ar":"لقياس اللعب الصوتي والمناغاة، وهما ضروريان لتطوير التحكم الصوتي."},"application":{"en":"Listen for changes in pitch or volume during babbling.","ar":"استمع للتغيرات في طبقة الصوت أو مستوى الصوت أثناء المناغاة."},"scoring":{"en":"1 point for 10 sounds/25 total; 1/2 point for 5 sounds/25 total.","ar":"درجة واحدة لـ 10 أصوات/25 إجمالاً؛ نصف درجة لـ 5 أصوات/25 إجمالاً."}},{"id":"v1-4","level":1,"category":"Vocal","milestone":4,"text":{"en":"Spontaneously emits 5 different whole-word approximations","ar":"يصدر 5 تقريبات مختلفة لكلمات كاملة بشكل عفوي"},"objective":{"en":"To measure vocal play and babbling, which are essential for developing vocal control.","ar":"لقياس اللعب الصوتي والمناغاة، وهما ضروريان لتطوير التحكم الصوتي."},"application":{"en":"Note when the child says things like \"mama\" or \"dada\" even if not in context.","ar":"لاحظ عندما يقول الطفل أشياء مثل \"ماما\" أو \"بابا\" حتى لو لم تكن في سياقها."},"scoring":{"en":"1 point for 5 approximations; 1/2 point for 2.","ar":"درجة واحدة لـ 5 تقريبات؛ نصف درجة لـ 2."}},{"id":"v1-5","level":1,"category":"Vocal","milestone":5,"text":{"en":"Spontaneously vocalizes 15 word approximations with appropriate intonation","ar":"ينطق 15 تقريباً لكلمات بنبرة مناسبة بشكل عفوي"},"objective":{"en":"To measure vocal play and babbling, which are essential for developing vocal control.","ar":"لقياس اللعب الصوتي والمناغاة، وهما ضروريان لتطوير التحكم الصوتي."},"application":{"en":"Observe if the child's babbling sounds like \"talking\" with recognizable words (e.g., \"get it,\" \"bye-bye\").","ar":"لاحظ ما إذا كانت مناغاة الطفل تبدو وكأنها \"تحدث\" بكلمات يمكن التعرف عليها (مثل \"هاتها\"، \"باي باي\")."},"scoring":{"en":"1 point for 15 approximations; 1/2 point for 8.","ar":"درجة واحدة لـ 15 تقريباً؛ نصف درجة لـ 8."}},{"id":"m2-6","level":2,"category":"Mand","milestone":6,"text":{"en":"Mands for 20 missing items without prompts","ar":"يطلب 20 شيئاً مفقوداً بدون مساعدة"},"objective":{"en":"To determine if the child can spontaneously ask for missing items, actions, and use 2+ word phrases.","ar":"لتحديد ما إذا كان الطفل يستطيع طلب الأشياء المفقودة، وطلب الأفعال، واستخدام عبارات مكونة من كلمتين أو أكثر."},"application":{"en":"Provide a toy or activity missing a necessary part (e.g., a juice box without a straw) and ask \"What do you need?\".","ar":"قدم لعبة أو نشاطاً ينقصه جزء ضروري (مثل علبة عصير بدون شفاطة) واسأل \"ماذا تحتاج؟\"."},"scoring":{"en":"1 point for 20 items; 1/2 point for 10.","ar":"درجة واحدة لـ 20 شيئاً؛ نصف درجة لـ 10."}},{"id":"m2-7","level":2,"category":"Mand","milestone":7,"text":{"en":"Mands for others to emit 5 different actions","ar":"يطلب من الآخرين القيام بـ 5 أفعال مختلفة"},"objective":{"en":"To determine if the child can spontaneously ask for missing items, actions, and use 2+ word phrases.","ar":"لتحديد ما إذا كان الطفل يستطيع طلب الأشياء المفقودة، وطلب الأفعال، واستخدام عبارات مكونة من كلمتين أو أكثر."},"application":{"en":"Contrive situations where an action is needed (e.g., \"push\" on a swing or \"open\" a door).","ar":"قم بافتعال مواقف تتطلب فعلاً (مثل \"ادفع\" في الأرجوحة أو \"افتح\" الباب)."},"scoring":{"en":"1 point for 5 actions; 1/2 point for 2.","ar":"درجة واحدة لـ 5 أفعال؛ نصف درجة لفعلين."}},{"id":"m2-8","level":2,"category":"Mand","milestone":8,"text":{"en":"Emits 5 different mands containing 2+ words (not \"I want\")","ar":"يصدر 5 طلبات مختلفة تحتوي على كلمتين أو أكثر (ليس \"أريد\")"},"objective":{"en":"To determine if the child can spontaneously ask for missing items, actions, and use 2+ word phrases.","ar":"لتحديد ما إذا كان الطفل يستطيع طلب الأشياء المفقودة، وطلب الأفعال، واستخدام عبارات مكونة من كلمتين أو أكثر."},"application":{"en":"Observe the child's requests in a natural setting for variations like \"Go fast\" or \"More juice\".","ar":"لاحظ طلبات الطفل في بيئة طبيعية للتنويعات مثل \"اذهب بسرعة\" أو \"مزيد من العصير\"."},"scoring":{"en":"1 point for 5 different multi-word mands; 1/2 point for 2.","ar":"درجة واحدة لـ 5 طلبات مختلفة متعددة الكلمات؛ نصف درجة لطلبين."}},{"id":"m2-9","level":2,"category":"Mand","milestone":9,"text":{"en":"Spontaneously emits 15 different mands","ar":"يصدر 15 طلباً مختلفاً بشكل عفوي"},"objective":{"en":"To determine if the child can spontaneously ask for missing items, actions, and use 2+ word phrases.","ar":"لتحديد ما إذا كان الطفل يستطيع طلب الأشياء المفقودة، وطلب الأفعال، واستخدام عبارات مكونة من كلمتين أو أكثر."},"application":{"en":"Record unprompted requests across a 30-minute observation.","ar":"سجل الطلبات غير الموجهة خلال ملاحظة مدتها 30 دقيقة."},"scoring":{"en":"1 point for 15 different spontaneous mands; 1/2 point for 8.","ar":"درجة واحدة لـ 15 طلباً عفوياً مختلفاً؛ نصف درجة لـ 8."}},{"id":"m2-10","level":2,"category":"Mand","milestone":10,"text":{"en":"Emits 10 new mands without specific training","ar":"يصدر 10 طلبات جديدة بدون تدريب محدد"},"objective":{"en":"To determine if the child can spontaneously ask for missing items, actions, and use 2+ word phrases.","ar":"لتحديد ما إذا كان الطفل يستطيع طلب الأشياء المفقودة، وطلب الأفعال، واستخدام عبارات مكونة من كلمتين أو أكثر."},"application":{"en":"Record instances where a known tact or echoic transfers to a mand without direct teaching.","ar":"سجل الحالات التي تنتقل فيها التسمية أو الترديد المعروف إلى طلب دون تدريب مباشر."},"scoring":{"en":"1 point for 10 new mands; 1/2 point for 5.","ar":"درجة واحدة لـ 10 طلبات جديدة؛ نصف درجة لـ 5."}},{"id":"t2-6","level":2,"category":"Tact","milestone":6,"text":{"en":"Tacts 25 items when asked \"What's that?\"","ar":"يسمي 25 شيئاً عند سؤاله \"ما هذا؟\""},"objective":{"en":"To expand the tact repertoire to include verbs and two-component combinations.","ar":"لتوسيع حصيلة التسمية لتشمل الأفعال والتركيبات المكونة من جزئين."},"application":{"en":"Use common objects or pictures from the child's environment.","ar":"استخدم أشياء شائعة أو صوراً من بيئة الطفل."},"scoring":{"en":"1 point for 25 items; 1/2 point for 20.","ar":"درجة واحدة لـ 25 شيئاً؛ نصف درجة لـ 20."}},{"id":"t2-7","level":2,"category":"Tact","milestone":7,"text":{"en":"Generalizes tacts across 3 examples of 50 items","ar":"يعمم التسمية عبر 3 أمثلة لـ 50 شيئاً"},"objective":{"en":"To expand the tact repertoire to include verbs and two-component combinations.","ar":"لتوسيع حصيلة التسمية لتشمل الأفعال والتركيبات المكونة من جزئين."},"application":{"en":"Present three variations of a known item (e.g., different types of cars).","ar":"قدم ثلاثة تنويعات لشيء معروف (مثل أنواع مختلفة من السيارات)."},"scoring":{"en":"1 point for 50 items (3 examples each); 1/2 point for 50 items (2 examples each).","ar":"درجة واحدة لـ 50 شيئاً (3 أمثلة لكل منها)؛ نصف درجة لـ 50 شيئاً (مثالان لكل منهما)."}},{"id":"t2-8","level":2,"category":"Tact","milestone":8,"text":{"en":"Tacts 10 actions","ar":"يسمي 10 أفعال"},"objective":{"en":"To expand the tact repertoire to include verbs and two-component combinations.","ar":"لتوسيع حصيلة التسمية لتشمل الأفعال والتركيبات المكونة من جزئين."},"application":{"en":"Ask \"What am I doing?\" while performing actions like jumping or eating.","ar":"اسأل \"ماذا أفعل؟\" أثناء القيام بأفعال مثل القفز أو الأكل."},"scoring":{"en":"1 point for 10 actions; 1/2 point for 5.","ar":"درجة واحدة لـ 10 أفعال؛ نصف درجة لـ 5."}},{"id":"t2-9","level":2,"category":"Tact","milestone":9,"text":{"en":"Tacts 50 two-component verb-noun or noun-verb combinations","ar":"يسمي 50 تركيبة من فعل واسم أو اسم وفعل"},"objective":{"en":"To expand the tact repertoire to include verbs and two-component combinations.","ar":"لتوسيع حصيلة التسمية لتشمل الأفعال والتركيبات المكونة من جزئين."},"application":{"en":"Present moving stimuli (e.g., a \"jumping monkey\") and ask what the child sees.","ar":"قدم مثيرات متحركة (مثل \"قرد يقفز\") واسأل عما يراه الطفل."},"scoring":{"en":"1 point for 50 combinations; 1/2 point for 25.","ar":"درجة واحدة لـ 50 تركيبة؛ نصف درجة لـ 25."}},{"id":"t2-10","level":2,"category":"Tact","milestone":10,"text":{"en":"Tacts a total of 200 nouns and/or verbs","ar":"يسمي ما مجموعه 200 اسم و/أو فعل"},"objective":{"en":"To expand the tact repertoire to include verbs and two-component combinations.","ar":"لتوسيع حصيلة التسمية لتشمل الأفعال والتركيبات المكونة من جزئين."},"application":{"en":"Use a cumulative list of all known labels.","ar":"استخدم قائمة تراكمية لجميع التسميات المعروفة."},"scoring":{"en":"1 point for 200 items; 1/2 point for 150.","ar":"درجة واحدة لـ 200 شيء؛ نصف درجة لـ 150."}},{"id":"l2-6","level":2,"category":"Listener","milestone":6,"text":{"en":"Selects correct item from a messy array of 6 (40 items)","ar":"يختار الشيء الصحيح من مجموعة فوضوية مكونة من 6 (40 شيئاً)"},"objective":{"en":"To develop the ability to discriminate between items in large arrays and follow complex instructions.","ar":"لتطوير القدرة على التمييز بين الأشياء في مجموعات كبيرة واتباع تعليمات معقدة."},"application":{"en":"Use random positioning for 6 items and ask \"Find [item]\".","ar":"استخدم وضعاً عشوائياً لـ 6 أشياء واسأل \"ابحث عن [الشيء]\"."},"scoring":{"en":"1 point for 40 items; 1/2 point for 25.","ar":"درجة واحدة لـ 40 شيئاً؛ نصف درجة لـ 25."}},{"id":"l2-7","level":2,"category":"Listener","milestone":7,"text":{"en":"Generalizes listener discriminations (array of 8) for 3 examples of 50 items","ar":"يعمم تمييز المستمع (مجموعة من 8) لـ 3 أمثلة لـ 50 شيئاً"},"objective":{"en":"To develop the ability to discriminate between items in large arrays and follow complex instructions.","ar":"لتطوير القدرة على التمييز بين الأشياء في مجموعات كبيرة واتباع تعليمات معقدة."},"application":{"en":"Present variations of an item in a large messy array.","ar":"قدم تنويعات لشيء في مجموعة فوضوية كبيرة."},"scoring":{"en":"1 point for 50 items (3 examples); 1/2 point for 25 items (2 examples).","ar":"درجة واحدة لـ 50 شيئاً (3 أمثلة)؛ نصف درجة لـ 25 شيئاً (مثالان)."}},{"id":"l2-8","level":2,"category":"Listener","milestone":8,"text":{"en":"Performs 10 specific motor actions on command","ar":"يؤدي 10 حركات حركية محددة بناءً على أمر"},"objective":{"en":"To develop the ability to discriminate between items in large arrays and follow complex instructions.","ar":"لتطوير القدرة على التمييز بين الأشياء في مجموعات كبيرة واتباع تعليمات معقدة."},"application":{"en":"Verbal command without imitation (e.g., \"Can you hop?\").","ar":"أمر لفظي دون تقليد (مثلاً: \"هل يمكنك القفز؟\")."},"scoring":{"en":"1 point for 10 actions; 1/2 point for 5.","ar":"درجة واحدة لـ 10 أفعال؛ نصف درجة لـ 5."}},{"id":"l2-9","level":2,"category":"Listener","milestone":9,"text":{"en":"Follows 50 two-component noun-verb/verb-noun instructions","ar":"يتبع 50 تعليمة مكونة من جزئين (اسم وفعل أو فعل واسم)"},"objective":{"en":"To develop the ability to discriminate between items in large arrays and follow complex instructions.","ar":"لتطوير القدرة على التمييز بين الأشياء في مجموعات كبيرة واتباع تعليمات معقدة."},"application":{"en":"E.g., \"Push the swing\" or \"Touch the sleeping baby\".","ar":"مثلاً: \"ادفع الأرجوحة\" أو \"المس الطفل النائم\"."},"scoring":{"en":"1 point for 50 instructions; 1/2 point for 25.","ar":"درجة واحدة لـ 50 تعليمة؛ نصف درجة لـ 25."}},{"id":"l2-10","level":2,"category":"Listener","milestone":10,"text":{"en":"Selects 250 items in a book, scene, or natural environment","ar":"يختار 250 شيئاً في كتاب أو مشهد أو بيئة طبيعية"},"objective":{"en":"To develop the ability to discriminate between items in large arrays and follow complex instructions.","ar":"لتطوير القدرة على التمييز بين الأشياء في مجموعات كبيرة واتباع تعليمات معقدة."},"application":{"en":"Name items in complex scenes and have the child point.","ar":"سمِّ أشياء في مشاهد معقدة واطلب من الطفل الإشارة إليها."},"scoring":{"en":"1 point for 250 items; 1/2 point for 150.","ar":"درجة واحدة لـ 250 شيئاً؛ نصف درجة لـ 150."}},{"id":"vp2-6","level":2,"category":"VP/MTS","milestone":6,"text":{"en":"Matches 25 non-identical items in an array of 6","ar":"يطابق 25 شيئاً غير متماثل في مجموعة من 6"},"objective":{"en":"To strengthen visual discrimination skills by matching non-identical items and sorting items by category.","ar":"لتعزيز مهارات التمييز البصري من خلال مطابقة الأشياء غير المتماثلة وتصنيف الأشياء حسب الفئة."},"application":{"en":"Present an item (e.g., a red car) and ask the child to find a different car (e.g., a blue car) in a group.","ar":"قدم شيئاً (مثلاً: سيارة حمراء) واطلب من الطفل العثور على سيارة مختلفة (مثلاً: سيارة زرقاء) في مجموعة."},"scoring":{"en":"1 point for 25 items; 1/2 point for 15.","ar":"درجة واحدة لـ 25 شيئاً؛ نصف درجة لـ 15."}},{"id":"vp2-7","level":2,"category":"VP/MTS","milestone":7,"text":{"en":"Sorts similar items from 5 different categories (e.g., animals, clothes)","ar":"يصنف أشياء متشابهة من 5 فئات مختلفة (مثل الحيوانات، الملابس)"},"objective":{"en":"To strengthen visual discrimination skills by matching non-identical items and sorting items by category.","ar":"لتعزيز مهارات التمييز البصري من خلال مطابقة الأشياء غير المتماثلة وتصنيف الأشياء حسب الفئة."},"application":{"en":"Present 5 categories (e.g., animals, clothes) and have the child sort items into groups.","ar":"قدم 5 فئات (مثل حيوانات، ملابس) واطلب من الطفل فرز الأشياء في مجموعات."},"scoring":{"en":"1 point for 5 categories; 1/2 point for 3.","ar":"درجة واحدة لـ 5 فئات؛ نصف درجة لـ 3."}},{"id":"vp2-8","level":2,"category":"VP/MTS","milestone":8,"text":{"en":"Matches 25 non-identical items to a sample in an array of 10","ar":"يطابق 25 شيئاً غير متماثل مع عينة في مجموعة من 10"},"objective":{"en":"To strengthen visual discrimination skills by matching non-identical items and sorting items by category.","ar":"لتعزيز مهارات التمييز البصري من خلال مطابقة الأشياء غير المتماثلة وتصنيف الأشياء حسب الفئة."},"application":{"en":"Show a sample (e.g., a spoon) and have the child find the match in an array of 10.","ar":"اعرض عينة (مثلاً: ملعقة) واطلب من الطفل العثور على المطابق في مجموعة من 10."},"scoring":{"en":"1 point for 25 items; 1/2 point for 15.","ar":"درجة واحدة لـ 25 شيئاً؛ نصف درجة لـ 15."}},{"id":"vp2-9","level":2,"category":"VP/MTS","milestone":9,"text":{"en":"Completes 10 different block designs, parquetry, or similar tasks","ar":"يكمل 10 تصاميم مكعبات مختلفة أو مهام مماثلة"},"objective":{"en":"To strengthen visual discrimination skills by matching non-identical items and sorting items by category.","ar":"لتعزيز مهارات التمييز البصري من خلال مطابقة الأشياء غير المتماثلة وتصنيف الأشياء حسب الفئة."},"application":{"en":"Use puzzles with 10 or more pieces or block design cards.","ar":"استخدم ألغازاً مكونة من 10 قطع أو أكثر أو بطاقات تصميم المكعبات."},"scoring":{"en":"1 point for 10 designs; 1/2 point for 5.","ar":"درجة واحدة لـ 10 تصاميم؛ نصف درجة لـ 5."}},{"id":"vp2-10","level":2,"category":"VP/MTS","milestone":10,"text":{"en":"Matches 25 non-identical items in a messy array of 10 with 3 similar distractors","ar":"يطابق 25 شيئاً غير متماثل في مجموعة فوضوية من 10 مع 3 مشتتات متشابهة"},"objective":{"en":"To strengthen visual discrimination skills by matching non-identical items and sorting items by category.","ar":"لتعزيز مهارات التمييز البصري من خلال مطابقة الأشياء غير المتماثلة وتصنيف الأشياء حسب الفئة."},"application":{"en":"Present pictures of very similar items (e.g., different types of dogs) and ask for a match.","ar":"قدم صوراً لأشياء متشابهة جداً (مثل أنواع مختلفة من الكلاب) واطلب المطابقة."},"scoring":{"en":"1 point for 25 items; 1/2 point for 15.","ar":"درجة واحدة لـ 25 شيئاً؛ نصف درجة لـ 15."}},{"id":"p2-6","level":2,"category":"Play","milestone":6,"text":{"en":"Searches for a missing or hidden object when it is not in view","ar":"يبحث عن شيء مفقود أو مخفي عندما لا يكون في مرأى العين"},"objective":{"en":"To determine if the child can search for items and engage in independent play with multi-part toys.","ar":"لتحديد ما إذا كان الطفل يستطيع البحث عن الأشياء والانخراط في اللعب المستقل بألعاب متعددة الأجزاء."},"application":{"en":"Hide a favorite toy under a blanket and see if the child looks for it.","ar":"خبئ لعبة مفضلة تحت بطانية وانظر ما إذا كان الطفل يبحث عنها."},"scoring":{"en":"1 point for searching for 5 different items; 1/2 point for 2.","ar":"درجة واحدة للبحث عن 5 أشياء مختلفة؛ نصف درجة لشيئين."}},{"id":"p2-7","level":2,"category":"Play","milestone":7,"text":{"en":"Independently assembles 5 different toys that have multiple parts","ar":"يركب بشكل مستقل 5 ألعاب مختلفة تحتوي على أجزاء متعددة"},"objective":{"en":"To determine if the child can search for items and engage in independent play with multi-part toys.","ar":"لتحديد ما إذا كان الطفل يستطيع البحث عن الأشياء والانخراط في اللعب المستقل بألعاب متعددة الأجزاء."},"application":{"en":"Observe the child putting together a Mr. Potato Head or stacking blocks.","ar":"لاحظ الطفل وهو يركب \"مستر بطاطس\" أو يرص المكعبات."},"scoring":{"en":"1 point for 5 toys; 1/2 point for 3.","ar":"درجة واحدة لـ 5 ألعاب؛ نصف درجة لـ 3 ألعاب."}},{"id":"p2-8","level":2,"category":"Play","milestone":8,"text":{"en":"Independently engages in 2 different sets of play behavior for 5 minutes","ar":"ينخرط بشكل مستقل في مجموعتين مختلفتين من سلوك اللعب لمدة 5 دقائق"},"objective":{"en":"To determine if the child can search for items and engage in independent play with multi-part toys.","ar":"لتحديد ما إذا كان الطفل يستطيع البحث عن الأشياء والانخراط في اللعب المستقل بألعاب متعددة الأجزاء."},"application":{"en":"Observe the child playing with a doll and then moving to a truck for a total of 5 minutes.","ar":"لاحظ الطفل وهو يلعب بدمية ثم ينتقل إلى شاحنة لمدة إجمالية قدرها 5 دقائق."},"scoring":{"en":"1 point for 5 minutes; 1/2 point for 2 minutes.","ar":"درجة واحدة لـ 5 دقائق؛ نصف درجة لدقيقتين."}},{"id":"p2-9","level":2,"category":"Play","milestone":9,"text":{"en":"Independently engages in 5 minutes of pretend play","ar":"ينخرط بشكل مستقل في 5 دقائق من اللعب التخيلي"},"objective":{"en":"To determine if the child can search for items and engage in independent play with multi-part toys.","ar":"لتحديد ما إذا كان الطفل يستطيع البحث عن الأشياء والانخراط في اللعب المستقل بألعاب متعددة الأجزاء."},"application":{"en":"Observe the child \"cooking\" in a play kitchen or \"driving\" a car.","ar":"لاحظ الطفل وهو \"يطبخ\" في مطبخ اللعب أو \"يقود\" سيارة."},"scoring":{"en":"1 point for 5 minutes; 1/2 point for 2 minutes.","ar":"درجة واحدة لـ 5 دقائق؛ نصف درجة لدقيقتين."}},{"id":"p2-10","level":2,"category":"Play","milestone":10,"text":{"en":"Independently assembles 10 different toys that have multiple parts","ar":"يركب بشكل مستقل 10 ألعاب مختلفة تحتوي على أجزاء متعددة"},"objective":{"en":"To determine if the child can search for items and engage in independent play with multi-part toys.","ar":"لتحديد ما إذا كان الطفل يستطيع البحث عن الأشياء والانخراط في اللعب المستقل بألعاب متعددة الأجزاء."},"application":{"en":"Observe the child assembling various multi-part toys.","ar":"لاحظ الطفل وهو يركب ألعاباً متنوعة متعددة الأجزاء."},"scoring":{"en":"1 point for 10 toys; 1/2 point for 5.","ar":"درجة واحدة لـ 10 ألعاب؛ نصف درجة لـ 5 ألعاب."}},{"id":"s2-6","level":2,"category":"Social","milestone":6,"text":{"en":"Initiates a physical interaction with a peer 2 times","ar":"يبدأ تفاعلاً جسدياً مع قرين مرتين"},"objective":{"en":"To determine if the child will initiate nonverbal or verbal interaction with other children.","ar":"تحديد ما إذا كان الطفل سيبدأ تفاعلاً غير لفظي أو لفظي مع الأطفال الآخرين."},"application":{"en":"Observe play settings for behaviors like tagging a peer or pulling a peer toward an activity.","ar":"لاحظ إعدادات اللعب لسلوكيات مثل لمس القرين أو سحب القرين نحو نشاط ما."},"scoring":{"en":"1 point for 2 times (negative initiations like pushing do not count); 1/2 point for 1 time.","ar":"درجة واحدة لمرتين (المبادرات السلبية مثل الدفع لا تحتسب)؛ نصف درجة لمرة واحدة."}},{"id":"s2-7","level":2,"category":"Social","milestone":7,"text":{"en":"Spontaneously mands to peers 5 times","ar":"يطلب من الأقران بشكل عفوي 5 مرات"},"objective":{"en":"To determine if the child will request items or actions from a peer without adult prompts.","ar":"تحديد ما إذا كان الطفل سيطلب أشياء أو أفعالاً من قرين دون توجيهات من الكبار."},"application":{"en":"Observe for mands like \"my turn,\" \"push me,\" or \"look\".","ar":"لاحظ الطلبات مثل \"دوري\"، \"ادفعني\"، أو \"انظر\"."},"scoring":{"en":"1 point for 5 mands (at least 2 different types); 1/2 point for 2 mands.","ar":"درجة واحدة لـ 5 طلبات (على الأقل نوعان مختلفان)؛ نصف درجة لطلبين."}},{"id":"s2-8","level":2,"category":"Social","milestone":8,"text":{"en":"Engages in sustained social play with peers for 3 minutes without adult prompts or reinforcement","ar":"ينخرط في لعب اجتماعي مستمر مع الأقران لمدة 3 دقائق دون توجيهات أو تعزيز من الكبار"},"objective":{"en":"To determine if a child will play cooperatively for a sustained period.","ar":"تحديد ما إذا كان الطفل سيلعب بشكل تعاوني لفترة مستمرة."},"application":{"en":"Observe activities involving interaction, such as building Legos together or playing in a playhouse.","ar":"لاحظ الأنشطة التي تتضمن تفاعلاً، مثل بناء الليغو معاً أو اللعب في بيت اللعب."},"scoring":{"en":"1 point for 5 minutes of specific verbal or nonverbal interaction; 1/2 point for 2 minutes.","ar":"درجة واحدة لـ 5 دقائق من التفاعل اللفظي أو غير اللفظي المحدد؛ نصف درجة لدقيقتين."}},{"id":"s2-9","level":2,"category":"Social","milestone":9,"text":{"en":"Spontaneously responds to the mands from peers 5 times","ar":"يستجيب لطلبات الأقران بشكل عفوي 5 مرات"},"objective":{"en":"To determine if the child attends to and complies with the requests of peers.","ar":"تحديد ما إذا كان الطفل ينتبه لمطالب الأقران ويمتثل لها."},"application":{"en":"Observe if the child gives a toy when asked or follows a peer's instruction like \"pull me\".","ar":"لاحظ ما إذا كان الطفل يعطي لعبة عند طلبها أو يتبع تعليمات القرين مثل \"اسحبني\"."},"scoring":{"en":"1 point for 5 times (at least 2 different mands); 1/2 point for 2 times.","ar":"درجة واحدة لـ 5 مرات (على الأقل طلبان مختلفان)؛ نصف درجة لمرتين."}},{"id":"s2-10","level":2,"category":"Social","milestone":10,"text":{"en":"Spontaneously mands to peers to participate in games, social play, etc., 2 times","ar":"يطلب من الأقران بشكل عفوي المشاركة في الألعاب، اللعب الاجتماعي، إلخ، مرتين"},"objective":{"en":"To determine if a child invites another child to join an activity.","ar":"تحديد ما إذا كان الطفل يدعو طفلاً آخر للانضمام إلى نشاط ما."},"application":{"en":"Listen for invitations like \"come play with me\" or \"let's be monsters\".","ar":"استمع للدعوات مثل \"تعال العب معي\" أو \"لنكن وحوشاً\"."},"scoring":{"en":"1 point for 2 times; 1/2 point for 1 time.","ar":"درجة واحدة لمرتين؛ نصف درجة لمرة واحدة."}},{"id":"e2-6","level":2,"category":"Echoic","milestone":6,"text":{"en":"Scores at least 50 on the EESA subtest","ar":"يسجل 50 على الأقل في اختبار EESA"},"objective":{"en":"To evaluate the child’s ability to repeat complex speech models.","ar":"لتقييم قدرة الطفل على تكرار نماذج الكلام المعقدة."},"application":{"en":"Tasks are scored based on the Early Echoic Skills Assessment.","ar":"يتم تسجيل المهام بناءً على تقييم مهارات الترديد المبكرة (EESA)."},"scoring":{"en":"1 point for score of 50 on EESA.","ar":"درجة واحدة للحصول على 50 في EESA."}},{"id":"e2-7","level":2,"category":"Echoic","milestone":7,"text":{"en":"Scores at least 60 on the EESA subtest","ar":"يسجل 60 على الأقل في اختبار EESA"},"objective":{"en":"To evaluate the child’s ability to repeat complex speech models.","ar":"لتقييم قدرة الطفل على تكرار نماذج الكلام المعقدة."},"application":{"en":"Tasks are scored based on the Early Echoic Skills Assessment.","ar":"يتم تسجيل المهام بناءً على تقييم مهارات الترديد المبكرة (EESA)."},"scoring":{"en":"1 point for score of 60 on EESA.","ar":"درجة واحدة للحصول على 60 في EESA."}},{"id":"e2-8","level":2,"category":"Echoic","milestone":8,"text":{"en":"Scores at least 70 on the EESA subtest","ar":"يسجل 70 على الأقل في اختبار EESA"},"objective":{"en":"To evaluate the child’s ability to repeat complex speech models.","ar":"لتقييم قدرة الطفل على تكرار نماذج الكلام المعقدة."},"application":{"en":"Tasks are scored based on the Early Echoic Skills Assessment.","ar":"يتم تسجيل المهام بناءً على تقييم مهارات الترديد المبكرة (EESA)."},"scoring":{"en":"1 point for score of 70 on EESA.","ar":"درجة واحدة للحصول على 70 في EESA."}},{"id":"e2-9","level":2,"category":"Echoic","milestone":9,"text":{"en":"Scores at least 80 on the EESA subtest","ar":"يسجل 80 على الأقل في اختبار EESA"},"objective":{"en":"To evaluate the child’s ability to repeat complex speech models.","ar":"لتقييم قدرة الطفل على تكرار نماذج الكلام المعقدة."},"application":{"en":"Tasks are scored based on the Early Echoic Skills Assessment.","ar":"يتم تسجيل المهام بناءً على تقييم مهارات الترديد المبكرة (EESA)."},"scoring":{"en":"1 point for score of 80 on EESA.","ar":"درجة واحدة للحصول على 80 في EESA."}},{"id":"e2-10","level":2,"category":"Echoic","milestone":10,"text":{"en":"Scores at least 90 on the EESA subtest","ar":"يسجل 90 على الأقل في اختبار EESA"},"objective":{"en":"To evaluate the child’s ability to repeat complex speech models.","ar":"لتقييم قدرة الطفل على تكرار نماذج الكلام المعقدة."},"application":{"en":"Tasks are scored based on the Early Echoic Skills Assessment.","ar":"يتم تسجيل المهام بناءً على تقييم مهارات الترديد المبكرة (EESA)."},"scoring":{"en":"1 point for score of 90 on EESA.","ar":"درجة واحدة للحصول على 90 في EESA."}},{"id":"lr2-6","level":2,"category":"LRFFC","milestone":6,"text":{"en":"Selects 5 different items from an array of 8 given a sound associated with the item","ar":"يختار 5 أشياء مختلفة من مجموعة من 8 عند سماع صوت مرتبط بالشيء"},"objective":{"en":"To develop the ability to select items based on their function, feature, or category.","ar":"لتطوير القدرة على اختيار الأشياء بناءً على وظيفتها أو ميزتها أو فئتها."},"application":{"en":"Emit a sound (e.g., \"meow\") and have the child find the matching animal in an array of 8.","ar":"أصدر صوتاً (مثل \"مواء\") واطلب من الطفل العثور على الحيوان المطابق في مجموعة من 8."},"scoring":{"en":"1 point for 5 sounds; 1/2 point for 2.","ar":"درجة واحدة لـ 5 أصوات؛ نصف درجة لـ 2."}},{"id":"lr2-7","level":2,"category":"LRFFC","milestone":7,"text":{"en":"Selects 5 different foods or drinks from an array of 8 given their function","ar":"يختار 5 أطعمة أو مشروبات مختلفة من مجموعة من 8 بناءً على وظيفتها"},"objective":{"en":"To develop the ability to select items based on their function, feature, or category.","ar":"لتطوير القدرة على اختيار الأشياء بناءً على وظيفتها أو ميزتها أو فئتها."},"application":{"en":"Ask \"What do you eat?\" or \"What do you drink?\" in an array of 8.","ar":"اسأل \"ماذا تأكل؟\" أو \"ماذا تشرب؟\" في مجموعة من 8."},"scoring":{"en":"1 point for 5 foods/drinks; 1/2 point for 2.","ar":"درجة واحدة لـ 5 أطعمة/مشروبات؛ نصف درجة لـ 2."}},{"id":"lr2-8","level":2,"category":"LRFFC","milestone":8,"text":{"en":"Selects 25 different items from an array of 10 given their function, feature, or category","ar":"يختار 25 شيئاً مختلفاً من مجموعة من 10 بناءً على وظيفتها أو ميزتها أو فئتها"},"objective":{"en":"To develop the ability to select items based on their function, feature, or category.","ar":"لتطوير القدرة على اختيار الأشياء بناءً على وظيفتها أو ميزتها أو فئتها."},"application":{"en":"Present 25 fill-in phrases (e.g., \"You sleep in a...\") and have the child select from an array of 10.","ar":"قدم 25 عبارة تكملة (مثل \"تنام في الـ...\") واطلب الاختيار من مجموعة من 10."},"scoring":{"en":"1 point for 25 items; 1/2 point for 15.","ar":"درجة واحدة لـ 25 شيئاً؛ نصف درجة لـ 15."}},{"id":"lr2-9","level":2,"category":"LRFFC","milestone":9,"text":{"en":"Selects 25 different items from an array of 10 given 2 different components","ar":"يختار 25 شيئاً مختلفاً من مجموعة من 10 بناءً على مكونين مختلفين"},"objective":{"en":"To develop the ability to select items based on their function, feature, or category.","ar":"لتطوير القدرة على اختيار الأشياء بناءً على وظيفتها أو ميزتها أو فئتها."},"application":{"en":"Ask 25 questions (e.g., \"What flies?\") and have the child select from an array of 10.","ar":"اسأل 25 سؤالاً (مثل \"ماذا يطير؟\") واطلب الاختيار من مجموعة من 10."},"scoring":{"en":"1 point for 25 items; 1/2 point for 15.","ar":"درجة واحدة لـ 25 سؤالاً؛ نصف درجة لـ 15."}},{"id":"lr2-10","level":2,"category":"LRFFC","milestone":10,"text":{"en":"Spontaneously tacts the item on 50% of the LRFFC trials","ar":"يسمي الشيء تلقائياً في 50% من محاولات LRFFC"},"objective":{"en":"To develop the ability to select items based on their function, feature, or category.","ar":"لتطوير القدرة على اختيار الأشياء بناءً على وظيفتها أو ميزتها أو فئتها."},"application":{"en":"Observe if the child spontaneously tacts the item after selecting it in 50% of trials.","ar":"لاحظ ما إذا كان الطفل يسمي الشيء تلقائياً بعد اختياره في 50% من المحاولات."},"scoring":{"en":"1 point for 50% of trials; 1/2 point for 25%.","ar":"درجة واحدة لـ 50% من المحاولات؛ نصف درجة لـ 25%."}},{"id":"iv2-6","level":2,"category":"Intraverbal","milestone":6,"text":{"en":"Completes 10 different fill-in phrases of any type","ar":"يكمل 10 عبارات تكملة مختلفة من أي نوع"},"objective":{"en":"To develop conversation skills by completing phrases and answering simple questions.","ar":"لتطوير مهارات المحادثة من خلال إكمال العبارات والإجابة على الأسئلة البسيطة."},"application":{"en":"Present 10 fun fill-in phrases (e.g., \"Choo-choo goes the...\") and wait for a response.","ar":"قدم 10 عبارات تكملة ممتعة (مثل \"توت توت الـ...\") وانتظر الرد."},"scoring":{"en":"1 point for 10 phrases; 1/2 point for 5.","ar":"درجة واحدة لـ 10 عبارات؛ نصف درجة لـ 5."}},{"id":"iv2-7","level":2,"category":"Intraverbal","milestone":7,"text":{"en":"Provides first name when asked \"What is your name?\"","ar":"يذكر اسمه الأول عند سؤاله \"ما اسمك؟\""},"objective":{"en":"To develop conversation skills by completing phrases and answering simple questions.","ar":"لتطوير مهارات المحادثة من خلال إكمال العبارات والإجابة على الأسئلة البسيطة."},"application":{"en":"Ask the child \"What is your name?\".","ar":"اسأل الطفل \"ما اسمك؟\"."},"scoring":{"en":"1 point for providing first name; no 1/2 point.","ar":"درجة واحدة لذكر الاسم الأول؛ لا توجد نصف درجة."}},{"id":"iv2-8","level":2,"category":"Intraverbal","milestone":8,"text":{"en":"Completes 25 different fill-in phrases","ar":"يكمل 25 عبارة تكملة مختلفة"},"objective":{"en":"To develop conversation skills by completing phrases and answering simple questions.","ar":"لتطوير مهارات المحادثة من خلال إكمال العبارات والإجابة على الأسئلة البسيطة."},"application":{"en":"Present 25 varied fill-in phrases.","ar":"قدم 25 عبارة تكملة متنوعة."},"scoring":{"en":"1 point for 25 phrases; 1/2 point for 15.","ar":"درجة واحدة لـ 25 عبارة؛ نصف درجة لـ 15."}},{"id":"iv2-9","level":2,"category":"Intraverbal","milestone":9,"text":{"en":"Answers 25 different \"what\" questions","ar":"يجيب على 25 سؤال \"ماذا\" مختلفاً"},"objective":{"en":"To develop conversation skills by completing phrases and answering simple questions.","ar":"لتطوير مهارات المحادثة من خلال إكمال العبارات والإجابة على الأسئلة البسيطة."},"application":{"en":"Ask 25 \"what\" questions (e.g., \"What do you eat?\").","ar":"اسأل 25 سؤال \"ماذا\" (مثل \"ماذا تأكل؟\")."},"scoring":{"en":"1 point for 25 questions; 1/2 point for 15.","ar":"درجة واحدة لـ 25 سؤالاً؛ نصف درجة لـ 15."}},{"id":"iv2-10","level":2,"category":"Intraverbal","milestone":10,"text":{"en":"Answers 25 different \"who\" or \"where\" questions","ar":"يجيب على 25 سؤال \"من\" أو \"أين\" مختلفاً"},"objective":{"en":"To develop conversation skills by completing phrases and answering simple questions.","ar":"لتطوير مهارات المحادثة من خلال إكمال العبارات والإجابة على الأسئلة البسيطة."},"application":{"en":"Ask 25 \"who\" or \"where\" questions (e.g., \"Where do you sleep?\").","ar":"اسأل 25 سؤال \"من\" أو \"أين\" (مثل \"أين تنام؟\")."},"scoring":{"en":"1 point for 25 questions; 1/2 point for 15.","ar":"درجة واحدة لـ 25 سؤالاً؛ نصف درجة لـ 15."}},{"id":"cl2-6","level":2,"category":"Classroom","milestone":6,"text":{"en":"Sits at a group snack or lunch table without negative behavior for 3 minutes","ar":"يجلس على طاولة وجبات خفيفة أو غداء جماعية دون سلوك سلبي لمدة 3 دقائق"},"objective":{"en":"To assess the child’s ability to follow daily routines, imitate peers, and learn in a group teaching format.","ar":"تقييم قدرة الطفل على اتباع الروتين اليومي، وتقليد الأقران، والتعلم في شكل تدريس جماعي."},"application":{"en":"Use standard classroom chairs and tables; tell the child to sit at the table while pointing to it.","ar":"استخدم كراسي وطاولات الفصل الدراسية القياسية؛ اطلب من الطفل الجلوس على الطاولة أثناء الإشارة إليها."},"scoring":{"en":"1 point if the child remains seated for 3 minutes without additional adult prompts; 1/2 point for 1 minute.","ar":"درجة واحدة إذا ظل الطفل جالساً لمدة 3 دقائق دون توجيهات إضافية من الكبار؛ نصف درجة لمدة دقيقة واحدة."}},{"id":"cl2-7","level":2,"category":"Classroom","milestone":7,"text":{"en":"Puts away personal items, lines up, and comes to a table with only 1 verbal prompt","ar":"يضع الأغراض الشخصية في مكانها، ويصطف، ويأتي إلى الطاولة بتوجيه لفظي واحد فقط"},"objective":{"en":"To assess the child’s ability to follow daily routines, imitate peers, and learn in a group teaching format.","ar":"تقييم قدرة الطفل على اتباع الروتين اليومي، وتقليد الأقران، والتعلم في شكل تدريس جماعي."},"application":{"en":"Present standard instructions such as \"put your lunch in your cubby\" or \"line up\".","ar":"قدم تعليمات قياسية مثل \"ضع غداءك في خزانتك\" أو \"اصطف\"."},"scoring":{"en":"1 point if the child complies when prompted only once; 1/2 point if 2 or more prompts are required.","ar":"درجة واحدة إذا امتثل الطفل عند توجيهه مرة واحدة فقط؛ نصف درجة إذا لزم الأمر توجيهان أو أكثر."}},{"id":"cl2-8","level":2,"category":"Classroom","milestone":8,"text":{"en":"Transitions between classroom activities with no more than 1 gestural or verbal prompt","ar":"ينتقل بين أنشطة الفصل بما لا يزيد عن توجيه إيمائي أو لفظي واحد"},"objective":{"en":"To assess the child’s ability to follow daily routines, imitate peers, and learn in a group teaching format.","ar":"تقييم قدرة الطفل على اتباع الروتين اليومي، وتقليد الأقران، والتعلم في شكل تدريس جماعي."},"application":{"en":"Observe the child's response to instructions to move to a new area, such as \"go to the circle group\".","ar":"لاحظ استجابة الطفل للتعليمات بالانتقال إلى منطقة جديدة، مثل \"اذهب إلى مجموعة الدائرة\"."},"scoring":{"en":"1 point if the child transitions successfully 80% of the time with one prompt and no negative behavior; 1/2 point if 2 or more prompts are needed.","ar":"درجة واحدة إذا انتقل الطفل بنجاح بنسبة 80% من الوقت بتوجيه واحد وبدون سلوك سلبي؛ نصف درجة إذا لزم الأمر توجيهان أو أكثر."}},{"id":"cl2-9","level":2,"category":"Classroom","milestone":9,"text":{"en":"Sits in a small group for 5 minutes without disruptive behavior or attempting to leave","ar":"يجلس في مجموعة صغيرة لمدة 5 دقائق دون سلوك تخريبي أو محاولة المغادرة"},"objective":{"en":"To assess the child’s ability to follow daily routines, imitate peers, and learn in a group teaching format.","ar":"تقييم قدرة الطفل على اتباع الروتين اليومي، وتقليد الأقران، والتعلم في شكل تدريس جماعي."},"application":{"en":"Observe the child in a group circle containing 3 or more children.","ar":"لاحظ الطفل في حلقة جماعية تضم 3 أطفال أو أكثر."},"scoring":{"en":"1 point for 5 minutes of participation without standing up or running away; 1/2 point for 2 minutes.","ar":"درجة واحدة لمدة 5 دقائق من المشاركة دون الوقوف أو الهروب؛ نصف درجة لمدة دقيقتين."}},{"id":"cl2-10","level":2,"category":"Classroom","milestone":10,"text":{"en":"Sits in a small group for 10 minutes, attends to teacher/material for 50% of period, and responds to 5 SDs","ar":"يجلس في مجموعة صغيرة لمدة 10 دقائق، وينتبه للمعلم/المادة بنسبة 50% من الفترة، ويستجيب لـ 5 تعليمات"},"objective":{"en":"To assess the child’s ability to follow daily routines, imitate peers, and learn in a group teaching format.","ar":"تقييم قدرة الطفل على اتباع الروتين اليومي، وتقليد الأقران، والتعلم في شكل تدريس جماعي."},"application":{"en":"Observe if the child makes eye contact with the teacher and responds to instructions (e.g., \"Sarah, pick a song\") in a circle or arts group.","ar":"لاحظ ما إذا كان الطفل يتواصل بصرياً مع المعلم ويستجيب للتعليمات (مثل \"سارة، اختاري أغنية\") في حلقة أو مجموعة فنون."},"scoring":{"en":"1 point for 10 minutes, 50% attending, and 5 correct responses; 1/2 point for 10 minutes, 33% attending, and 2 responses.","ar":"درجة واحدة لمدة 10 دقائق، وانتباه بنسبة 50%، و5 استجابات صحيحة؛ نصف درجة لمدة 10 دقائق، وانتباه بنسبة 33%، واستجابتين."}},{"id":"li2-6","level":2,"category":"Linguistics","milestone":6,"text":{"en":"Tacts 25 items with 2 words (e.g., \"big ball\")","ar":"يسمي 25 شيئاً بكلمتين (مثل \"كرة كبيرة\")"},"objective":{"en":"To evaluate the development of grammar and the use of different parts of speech.","ar":"لتقييم تطور القواعد واستخدام أجزاء الكلام المختلفة."},"application":{"en":"Observe if the child tacts 25 items using 2-word combinations.","ar":"لاحظ ما إذا كان الطفل يسمي 25 شيئاً باستخدام تركيبات من كلمتين (مثل \"كرة كبيرة\")."},"scoring":{"en":"1 point for 25 combinations; 1/2 point for 15.","ar":"درجة واحدة لـ 25 تركيبة؛ نصف درجة لـ 15."}},{"id":"li2-7","level":2,"category":"Linguistics","milestone":7,"text":{"en":"Uses 10 different verbs in any verbal operant","ar":"يستخدم 10 أفعال مختلفة في أي عملية لفظية"},"objective":{"en":"To evaluate the development of grammar and the use of different parts of speech.","ar":"لتقييم تطور القواعد واستخدام أجزاء الكلام المختلفة."},"application":{"en":"Observe the use of 10 different verbs in various contexts.","ar":"لاحظ استخدام 10 أفعال مختلفة في سياقات متنوعة."},"scoring":{"en":"1 point for 10 verbs; 1/2 point for 5.","ar":"درجة واحدة لـ 10 أفعال؛ نصف درجة لـ 5."}},{"id":"li2-8","level":2,"category":"Linguistics","milestone":8,"text":{"en":"Uses 10 different adjectives in any verbal operant","ar":"يستخدم 10 صفات مختلفة في أي عملية لفظية"},"objective":{"en":"To evaluate the development of grammar and the use of different parts of speech.","ar":"لتقييم تطور القواعد واستخدام أجزاء الكلام المختلفة."},"application":{"en":"Observe the use of 10 different adjectives to describe items.","ar":"لاحظ استخدام 10 صفات مختلفة لوصف الأشياء."},"scoring":{"en":"1 point for 10 adjectives; 1/2 point for 5.","ar":"درجة واحدة لـ 10 صفات؛ نصف درجة لـ 5."}},{"id":"li2-9","level":2,"category":"Linguistics","milestone":9,"text":{"en":"Uses 10 different prepositions in any verbal operant","ar":"يستخدم 10 حروف جر مختلفة في أي عملية لفظية"},"objective":{"en":"To evaluate the development of grammar and the use of different parts of speech.","ar":"لتقييم تطور القواعد واستخدام أجزاء الكلام المختلفة."},"application":{"en":"Observe the use of 10 different prepositions (e.g., \"on,\" \"under\").","ar":"لاحظ استخدام 10 حروف جر مختلفة (مثل \"فوق\"، \"تحت\")."},"scoring":{"en":"1 point for 10 prepositions; 1/2 point for 5.","ar":"درجة واحدة لـ 10 حروف جر؛ نصف درجة لـ 5."}},{"id":"li2-10","level":2,"category":"Linguistics","milestone":10,"text":{"en":"Uses 10 different pronouns in any verbal operant","ar":"يستخدم 10 ضمائر مختلفة في أي عملية لفظية"},"objective":{"en":"To evaluate the development of grammar and the use of different parts of speech.","ar":"لتقييم تطور القواعد واستخدام أجزاء الكلام المختلفة."},"application":{"en":"Observe the use of 10 different pronouns (e.g., \"I,\" \"you,\" \"he\").","ar":"لاحظ استخدام 10 ضمائر مختلفة (مثل \"أنا\"، \"أنت\"، \"هو\")."},"scoring":{"en":"1 point for 10 pronouns; 1/2 point for 5.","ar":"درجة واحدة لـ 10 ضمائر؛ نصف درجة لـ 5."}},{"id":"m3-11","level":3,"category":"Mand","milestone":11,"text":{"en":"Spontaneously mands for verbal information using a WH question word 5 times","ar":"يطلب معلومات لفظية بشكل عفوي باستخدام كلمة استفهام 5 مرات"},"objective":{"en":"To determine if the child can spontaneously ask for information, politely remove aversives, and use complex modifiers in requests.","ar":"تحديد ما إذا كان الطفل يستطيع طلب المعلومات بشكل عفوي، وإزالة المنفرات بأدب، واستخدام معدلات معقدة في الطلبات."},"application":{"en":"Observe if the child has an MO for an answer (e.g., asking \"What's that?\" about a new toy).","ar":"لاحظ ما إذا كان لدى الطفل دافع (MO) للحصول على إجابة (مثلاً، يسأل \"ما هذا؟\" عن لعبة جديدة)."},"scoring":{"en":"1 point for using at least 2 different WH words 5 times; 1/2 point for using one WH word 2 times.","ar":"درجة واحدة لاستخدام كلمتين استفهام مختلفتين على الأقل 5 مرات؛ نصف درجة لاستخدام كلمة استفهام واحدة مرتين."}},{"id":"m3-12","level":3,"category":"Mand","milestone":12,"text":{"en":"Politely mands to stop an undesirable activity or remove an aversive under 5 different circumstances","ar":"يطلب بأدب إيقاف نشاط غير مرغوب فيه أو إزالة منفر في 5 ظروف مختلفة"},"objective":{"en":"To determine if the child can spontaneously ask for information, politely remove aversives, and use complex modifiers in requests.","ar":"تحديد ما إذا كان الطفل يستطيع طلب المعلومات بشكل عفوي، وإزالة المنفرات بأدب، واستخدام معدلات معقدة في الطلبات."},"application":{"en":"Observe if the child uses words like \"No thank you\" or \"Please stop\" instead of negative behavior.","ar":"لاحظ ما إذا كان الطفل يستخدم كلمات مثل \"لا شكراً\" أو \"من فضلك توقف\" بدلاً من السلوك السلبي."},"scoring":{"en":"1 point for 5 circumstances; 1/2 point for 2 circumstances.","ar":"درجة واحدة لـ 5 ظروف؛ نصف درجة لظرفين."}},{"id":"m3-13","level":3,"category":"Mand","milestone":13,"text":{"en":"Mands with 10 different adjectives, prepositions, or adverbs","ar":"يطلب باستخدام 10 صفات أو حروف جر أو ظروف مختلفة"},"objective":{"en":"To determine if the child can spontaneously ask for information, politely remove aversives, and use complex modifiers in requests.","ar":"تحديد ما إذا كان الطفل يستطيع طلب المعلومات بشكل عفوي، وإزالة المنفرات بأدب، واستخدام معدلات معقدة في الطلبات."},"application":{"en":"Look for requests like \"I want the big chip\" or \"Go fast.\"","ar":"ابحث عن طلبات مثل \"أريد الشريحة الكبيرة\" أو \"اذهب بسرعة\"."},"scoring":{"en":"1 point for 10 total (at least 2 from each group); 1/2 point for 5 total.","ar":"درجة واحدة لـ 10 إجمالاً (على الأقل 2 من كل مجموعة)؛ نصف درجة لـ 5 إجمالاً."}},{"id":"m3-14","level":3,"category":"Mand","milestone":14,"text":{"en":"Gives directions, instructions, or explanations as to how to participate in an activity 5 times","ar":"يعطي توجيهات أو تعليمات أو تفسيرات حول كيفية المشاركة في نشاط ما 5 مرات"},"objective":{"en":"To determine if the child can spontaneously ask for information, politely remove aversives, and use complex modifiers in requests.","ar":"تحديد ما إذا كان الطفل يستطيع طلب المعلومات بشكل عفوي، وإزالة المنفرات بأدب، واستخدام معدلات معقدة في الطلبات."},"application":{"en":"Observe the child telling others how to play (e.g., \"You sit here while I get a book\").","ar":"لاحظ الطفل وهو يخبر الآخرين بكيفية اللعب (مثلاً، \"اجلس هنا بينما أحضر كتاباً\")."},"scoring":{"en":"1 point for 5 instances; 1/2 point for 2.","ar":"درجة واحدة لـ 5 حالات؛ نصف درجة لحالتين."}},{"id":"m3-15","level":3,"category":"Mand","milestone":15,"text":{"en":"Mands for others to attend to his own intraverbal behavior 5 times","ar":"يطلب من الآخرين الانتباه لسلوكه اللفظي الداخلي 5 مرات"},"objective":{"en":"To determine if the child can spontaneously ask for information, politely remove aversives, and use complex modifiers in requests.","ar":"تحديد ما إذا كان الطفل يستطيع طلب المعلومات بشكل عفوي، وإزالة المنفرات بأدب، واستخدام معدلات معقدة في الطلبات."},"application":{"en":"Look for phrases like \"Listen to me\" or \"I'm telling the story.\"","ar":"ابحث عن عبارات مثل \"استمع إلي\" أو \"أنا أروي القصة\"."},"scoring":{"en":"1 point for 5 instances; 1/2 point for 2.","ar":"درجة واحدة لـ 5 حالات؛ نصف درجة لحالتين."}},{"id":"t3-11","level":3,"category":"Tact","milestone":11,"text":{"en":"Tacts the color, shape, and function of 5 objects (15 trials) in mixed order","ar":"يسمي اللون والشكل والوظيفة لـ 5 أشياء (15 محاولة) بترتيب مختلط"},"objective":{"en":"To move from simple nouns/verbs to labeling properties, relations, and using complete sentences.","ar":"الانتقال من الأسماء/الأفعال البسيطة إلى تسمية الخصائص والعلاقات واستخدام جمل كاملة."},"application":{"en":"Mix questions like \"What color is this?\" and \"What do you do with this?\" for the same items.","ar":"امزج أسئلة مثل \"ما لون هذا؟\" و \"ماذا تفعل بهذا؟\" لنفس الأشياء."},"scoring":{"en":"1 point for all 15 trials; 1/2 point for tacting 2 features of 5 objects (10 trials).","ar":"درجة واحدة لجميع المحاولات الـ 15؛ نصف درجة لتسمية ميزتين لـ 5 أشياء (10 محاولات)."}},{"id":"t3-12","level":3,"category":"Tact","milestone":12,"text":{"en":"Tacts 4 prepositions and 4 pronouns","ar":"يسمي 4 حروف جر و 4 ضمائر"},"objective":{"en":"To move from simple nouns/verbs to labeling properties, relations, and using complete sentences.","ar":"الانتقال من الأسماء/الأفعال البسيطة إلى تسمية الخصائص والعلاقات واستخدام جمل كاملة."},"application":{"en":"Test spatial relations (in, on, under) and personal pronouns (I, you, mine).","ar":"اختبر العلاقات المكانية (في، على، تحت) والضمائر الشخصية (أنا، أنت، لي)."},"scoring":{"en":"1 point for 4 of each; 1/2 point for 4 total across both categories.","ar":"درجة واحدة لـ 4 من كل منهما؛ نصف درجة لـ 4 إجمالاً عبر الفئتين."}},{"id":"t3-13","level":3,"category":"Tact","milestone":13,"text":{"en":"Tacts 4 relative adjectives and 4 adverbs","ar":"يسمي 4 صفات نسبية و 4 ظروف"},"objective":{"en":"To move from simple nouns/verbs to labeling properties, relations, and using complete sentences.","ar":"الانتقال من الأسماء/الأفعال البسيطة إلى تسمية الخصائص والعلاقات واستخدام جمل كاملة."},"application":{"en":"Label properties like \"big/little\" and \"fast/slow.\"","ar":"تسمية الخصائص مثل \"كبير/صغير\" و \"سريع/بطيء\"."},"scoring":{"en":"1 point for 4 of each; 1/2 point for 4 total across both categories.","ar":"درجة واحدة لـ 4 من كل منهما؛ نصف درجة لـ 4 إجمالاً عبر الفئتين."}},{"id":"t3-14","level":3,"category":"Tact","milestone":14,"text":{"en":"Tacts with complete sentences containing 4 or more words, 20 times","ar":"يسمي بجمل كاملة تحتوي على 4 كلمات أو أكثر، 20 مرة"},"objective":{"en":"To move from simple nouns/verbs to labeling properties, relations, and using complete sentences.","ar":"الانتقال من الأسماء/الأفعال البسيطة إلى تسمية الخصائص والعلاقات واستخدام جمل كاملة."},"application":{"en":"Observe sentences like \"That is a big ice cream cone!\"","ar":"لاحظ جمل مثل \"هذا مخروط آيس كريم كبير!\"."},"scoring":{"en":"1 point for 20 sentences (4+ words); 1/2 point for 20 sentences (3+ words).","ar":"درجة واحدة لـ 20 جملة (4+ كلمات)؛ نصف درجة لـ 20 جملة (3+ كلمات)."}},{"id":"t3-15","level":3,"category":"Tact","milestone":15,"text":{"en":"Has a tact vocabulary of 1000 words","ar":"لديه حصيلة لغوية تسمية تبلغ 1000 كلمة"},"objective":{"en":"To move from simple nouns/verbs to labeling properties, relations, and using complete sentences.","ar":"الانتقال من الأسماء/الأفعال البسيطة إلى تسمية الخصائص والعلاقات واستخدام جمل كاملة."},"application":{"en":"Use an accumulated list or sample from a Pictionary book.","ar":"استخدم قائمة متراكمة أو عينة من كتاب صور."},"scoring":{"en":"1 point for 1000 words; 1/2 point for 750 words.","ar":"درجة واحدة لـ 1000 كلمة؛ نصف درجة لـ 750 كلمة."}},{"id":"l3-11","level":3,"category":"Listener","milestone":11,"text":{"en":"Selects items by color and shape from an array of 6 for 4 colors and 4 shapes","ar":"يختار الأشياء حسب اللون والشكل من مجموعة من 6 لـ 4 ألوان و 4 أشكال"},"objective":{"en":"To identify complex combinations of properties and follow multi-step instructions.","ar":"تحديد تركيبات معقدة من الخصائص واتباع تعليمات متعددة الخطوات."},"application":{"en":"Ask \"Find the red car\" in an array with blue cars and red balls.","ar":"اسأل \"ابحث عن السيارة الحمراء\" في مجموعة تحتوي على سيارات زرقاء وكرات حمراء."},"scoring":{"en":"1 point for 4 colors and 4 shapes; 1/2 point for 2 of each.","ar":"درجة واحدة لـ 4 ألوان و 4 أشكال؛ نصف درجة لـ 2 من كل منهما."}},{"id":"l3-12","level":3,"category":"Listener","milestone":12,"text":{"en":"Follows instructions involving 6 prepositions and 4 pronouns","ar":"يتبع التعليمات التي تتضمن 6 حروف جر و 4 ضمائر"},"objective":{"en":"To identify complex combinations of properties and follow multi-step instructions.","ar":"تحديد تركيبات معقدة من الخصائص واتباع تعليمات متعددة الخطوات."},"application":{"en":"Command the child to \"stand behind the chair\" or \"touch my ear.\"","ar":"اطلب من الطفل \"الوقوف خلف الكرسي\" أو \"لمس أذني\"."},"scoring":{"en":"1 point for 2 trials of 6 preps/4 pronouns; 1/2 point for 3 preps/2 pronouns.","ar":"درجة واحدة لمحاولتين لـ 6 حروف جر/4 ضمائر؛ نصف درجة لـ 3 حروف جر/ضميرين."}},{"id":"l3-13","level":3,"category":"Listener","milestone":13,"text":{"en":"Selects from array based on 4 relative adjectives and 4 relative adverbs","ar":"يختار من مجموعة بناءً على 4 صفات نسبية و 4 ظروف نسبية"},"objective":{"en":"To identify complex combinations of properties and follow multi-step instructions.","ar":"تحديد تركيبات معقدة من الخصائص واتباع تعليمات متعددة الخطوات."},"application":{"en":"Ask \"Which one is bigger?\" or \"Which word was louder?\".","ar":"اسأل \"أيهما أكبر؟\" أو \"أي كلمة كانت أعلى؟\"."},"scoring":{"en":"1 point for 4 pairs of each; 1/2 point for 2 pairs of each.","ar":"درجة واحدة لـ 4 أزواج من كل منهما؛ نصف درجة لزوجين من كل منهما."}},{"id":"l3-14","level":3,"category":"Listener","milestone":14,"text":{"en":"Follows 3-step directions for 10 different directions","ar":"يتبع توجيهات من 3 خطوات لـ 10 توجيهات مختلفة"},"objective":{"en":"To identify complex combinations of properties and follow multi-step instructions.","ar":"تحديد تركيبات معقدة من الخصائص واتباع تعليمات متعددة الخطوات."},"application":{"en":"\"Get your coat, hang it up, and sit down.\"","ar":"\"أحضر معطفك، علقه، واجلس\"."},"scoring":{"en":"1 point for 10 directions; 1/2 point for 5.","ar":"درجة واحدة لـ 10 توجيهات؛ نصف درجة لـ 5."}},{"id":"l3-15","level":3,"category":"Listener","milestone":15,"text":{"en":"Total listener repertoire of 1200 words","ar":"إجمالي حصيلة المستمع تبلغ 1200 كلمة"},"objective":{"en":"To identify complex combinations of properties and follow multi-step instructions.","ar":"تحديد تركيبات معقدة من الخصائص واتباع تعليمات متعددة الخطوات."},"application":{"en":"Tested or from an accumulated list of nouns, verbs, etc.","ar":"مختبر أو من قائمة متراكمة من الأسماء والأفعال وما إلى ذلك."},"scoring":{"en":"1 point for 1200 words; 1/2 point for 800 words.","ar":"درجة واحدة لـ 1200 كلمة؛ نصف درجة لـ 800 كلمة."}},{"id":"vp3-11","level":3,"category":"VP/MTS","milestone":11,"text":{"en":"Spontaneously matches part of an arts/crafts activity to a sample 2 times","ar":"يطابق تلقائياً جزءاً من نشاط فنون/حرف يدوية مع عينة مرتين"},"objective":{"en":"To assess abstract matching, categorization, and pattern extension.","ar":"تقييم المطابقة المجردة والتصنيف وتمديد الأنماط."},"application":{"en":"If a peer colors a sun yellow, the target child also picks yellow for their sun.","ar":"إذا قام أحد الأقران بتلوين شمس باللون الأصفر، فإن الطفل المستهدف يختار أيضاً اللون الأصفر لشمسه."},"scoring":{"en":"1 point for 2 instances; 1/2 point for 1.","ar":"درجة واحدة لحالتين؛ نصف درجة لحالة واحدة."}},{"id":"vp3-12","level":3,"category":"VP/MTS","milestone":12,"text":{"en":"Demonstrates generalized non-identical matching in messy array of 10 for 25 items","ar":"يظهر مطابقة غير متماثلة معممة في مجموعة فوضوية من 10 لـ 25 شيئاً"},"objective":{"en":"To assess abstract matching, categorization, and pattern extension.","ar":"تقييم المطابقة المجردة والتصنيف وتمديد الأنماط."},"application":{"en":"Matches a novel plastic pineapple to a picture of a pineapple on the first trial.","ar":"يطابق أناناساً بلاستيكياً جديداً بصورة أناناس في المحاولة الأولى."},"scoring":{"en":"1 point for 25 items; 1/2 point for 15.","ar":"درجة واحدة لـ 25 شيئاً؛ نصف درجة لـ 15 شيئاً."}},{"id":"vp3-13","level":3,"category":"VP/MTS","milestone":13,"text":{"en":"Completes 20 different block designs or shape puzzles with 8+ pieces","ar":"يكمل 20 تصميماً مختلفاً للمكعبات أو ألغاز الأشكال بـ 8 قطع أو أكثر"},"objective":{"en":"To assess abstract matching, categorization, and pattern extension.","ar":"تقييم المطابقة المجردة والتصنيف وتمديد الأنماط."},"application":{"en":"Use block design kits or parquetry puzzles and cards.","ar":"استخدم مجموعات تصميم المكعبات أو ألغاز الباركيه والبطاقات."},"scoring":{"en":"1 point for 20 designs (8+ pieces); 1/2 point for 20 designs (4+ pieces).","ar":"درجة واحدة لـ 20 تصميماً (8+ قطع)؛ نصف درجة لـ 20 تصميماً (4+ قطع)."}},{"id":"vp3-14","level":3,"category":"VP/MTS","milestone":14,"text":{"en":"Sorts 5 items from 5 different categories without a model","ar":"يصنف 5 أشياء من 5 فئات مختلفة بدون نموذج"},"objective":{"en":"To assess abstract matching, categorization, and pattern extension.","ar":"تقييم المطابقة المجردة والتصنيف وتمديد الأنماط."},"application":{"en":"Give a mix of 15 pictures (animals, clothing, etc.) to sort into piles.","ar":"أعطِ مزيجاً من 15 صورة (حيوانات، ملابس، إلخ) لتصنيفها في أكوام."},"scoring":{"en":"1 point for 5 categories; 1/2 point for 3 categories.","ar":"درجة واحدة لـ 5 فئات؛ نصف درجة لـ 3 فئات."}},{"id":"vp3-15","level":3,"category":"VP/MTS","milestone":15,"text":{"en":"Continues 20 three-step patterns or sequences","ar":"يواصل 20 نمطاً أو تسلسلاً من ثلاث خطوات"},"objective":{"en":"To assess abstract matching, categorization, and pattern extension.","ar":"تقييم المطابقة المجردة والتصنيف وتمديد الأنماط."},"application":{"en":"Pattern like \"red, blue, green\" must be continued using colored blocks.","ar":"يجب مواصلة نمط مثل \"أحمر، أزرق، أخضر\" باستخدام المكعبات الملونة."},"scoring":{"en":"1 point for 20 three-step patterns; 1/2 point for 20 two-step patterns.","ar":"درجة واحدة لـ 20 نمطاً من ثلاث خطوات؛ نصف درجة لـ 20 نمطاً من خطوتين."}},{"id":"p3-11","level":3,"category":"Play","milestone":11,"text":{"en":"Spontaneously engages in pretend play on 5 occasions","ar":"ينخرط تلقائياً في اللعب التخيلي في 5 مناسبات"},"objective":{"en":"To determine if a child can engage in sustained, creative, and pre-academic play.","ar":"تحديد ما إذا كان الطفل يستطيع الانخراط في لعب مستمر ومبدع وما قبل الأكاديمي."},"application":{"en":"Observe role-playing like a \"princess\" or \"cooking dinner.\"","ar":"لاحظ لعب الأدوار مثل \"أميرة\" أو \"طهي العشاء\"."},"scoring":{"en":"1 point for 5 occasions; 1/2 point for 2.","ar":"درجة واحدة لـ 5 مناسبات؛ نصف درجة لمناسبتين."}},{"id":"p3-12","level":3,"category":"Play","milestone":12,"text":{"en":"Repeats gross motor play to obtain a better effect for 2 activities","ar":"يكرر اللعب الحركي الكبير للحصول على تأثير أفضل لنشاطين"},"objective":{"en":"To determine if a child can engage in sustained, creative, and pre-academic play.","ar":"تحديد ما إذا كان الطفل يستطيع الانخراط في لعب مستمر ومبدع وما قبل الأكاديمي."},"application":{"en":"Kicking a ball until it hits a target or pumping a swing.","ar":"ركل الكرة حتى تصيب الهدف أو دفع الأرجوحة."},"scoring":{"en":"1 point for 2 activities; 1/2 point for 1.","ar":"درجة واحدة لنشاطين؛ نصف درجة لنشاط واحد."}},{"id":"p3-13","level":3,"category":"Play","milestone":13,"text":{"en":"Independently engages in arts and crafts for 5 minutes","ar":"ينخرط بشكل مستقل في الفنون والحرف اليدوية لمدة 5 دقائق"},"objective":{"en":"To determine if a child can engage in sustained, creative, and pre-academic play.","ar":"تحديد ما إذا كان الطفل يستطيع الانخراط في لعب مستمر ومبدع وما قبل الأكاديمي."},"application":{"en":"Drawing, coloring, or pasting without adult prompts.","ar":"الرسم أو التلوين أو اللصق بدون توجيهات من الكبار."},"scoring":{"en":"1 point for 5 minutes; 1/2 point for 2.","ar":"درجة واحدة لـ 5 دقائق؛ نصف درجة لدقيقتين."}},{"id":"p3-14","level":3,"category":"Play","milestone":14,"text":{"en":"Independently engages in sustained play for 10 minutes","ar":"ينخرط بشكل مستقل في اللعب المستمر لمدة 10 دقائق"},"objective":{"en":"To determine if a child can engage in sustained, creative, and pre-academic play.","ar":"تحديد ما إذا كان الطفل يستطيع الانخراط في لعب مستمر ومبدع وما قبل الأكاديمي."},"application":{"en":"Continuous play with Legos or a dollhouse without adult help.","ar":"اللعب المستمر بالمكعبات (ليغو) أو بيت الدمى بدون مساعدة الكبار."},"scoring":{"en":"1 point for 10 minutes; 1/2 point for 5.","ar":"درجة واحدة لـ 10 دقائق؛ نصف درجة لـ 5 دقائق."}},{"id":"p3-15","level":3,"category":"Play","milestone":15,"text":{"en":"Independently draws or writes in pre-academic books for 5 minutes","ar":"يرسم أو يكتب بشكل مستقل في كتب ما قبل الأكاديمية لمدة 5 دقائق"},"objective":{"en":"To determine if a child can engage in sustained, creative, and pre-academic play.","ar":"تحديد ما إذا كان الطفل يستطيع الانخراط في لعب مستمر ومبدع وما قبل الأكاديمي."},"application":{"en":"Completing mazes, dot-to-dot, or tracing in a workbook.","ar":"إكمال المتاهات، أو التوصيل بين النقاط، أو التتبع في كتاب تمارين."},"scoring":{"en":"1 point for 5 minutes; 1/2 point for 2.","ar":"درجة واحدة لـ 5 دقائق؛ نصف درجة لدقيقتين."}},{"id":"s3-11","level":3,"category":"Social","milestone":11,"text":{"en":"Spontaneously cooperates with a peer to accomplish a specific outcome 5 times","ar":"يتعاون تلقائياً مع أحد الأقران لتحقيق نتيجة محددة 5 مرات"},"objective":{"en":"To determine if the child engages in cooperative behavior without adult prompting.","ar":"تحديد ما إذا كان الطفل ينخرط في سلوك تعاوني دون توجيه من الكبار."},"application":{"en":"Observe tasks requiring two people, like one child holding a bucket while another pours water.","ar":"لاحظ المهام التي تتطلب شخصين، مثل طفل يمسك دلواً بينما يصب الآخر الماء."},"scoring":{"en":"1 point for 5 times; 1/2 point for 2 times.","ar":"درجة واحدة لـ 5 مرات؛ نصف درجة لمرتين."}},{"id":"s3-12","level":3,"category":"Social","milestone":12,"text":{"en":"Spontaneously mands to peers with a WH question 5 times","ar":"يطلب تلقائياً من الأقران باستخدام سؤال استفهام 5 مرات"},"objective":{"en":"To determine if the child asks peers for verbal information.","ar":"تحديد ما إذا كان الطفل يطلب من الأقران معلومات لفظية."},"application":{"en":"Observe if the child asks questions like \"Where is the red crayon?\" or \"What are you building?\".","ar":"لاحظ ما إذا كان الطفل يطرح أسئلة مثل \"أين التلوين الأحمر؟\" أو \"ماذا تبني؟\"."},"scoring":{"en":"1 point for 5 different mands; 1/2 point for 2.","ar":"درجة واحدة لـ 5 طلبات مختلفة؛ نصف درجة لطلبين."}},{"id":"s3-13","level":3,"category":"Social","milestone":13,"text":{"en":"Intraverbally responds to 5 different questions or statements from peers","ar":"يستجيب لفظياً لـ 5 أسئلة أو عبارات مختلفة من الأقران"},"objective":{"en":"To determine if the child responds verbally to a peer without adult prompting.","ar":"تحديد ما إذا كان الطفل يستجيب لفظياً لقرين دون توجيه من الكبار."},"application":{"en":"Observe for exchanges like a peer asking \"What do you have for lunch?\" and the child answering \"A sandwich\".","ar":"لاحظ التبادلات مثل سؤال القرين \"ماذا لديك للغداء؟\" وإجابة الطفل \"شطيرة\"."},"scoring":{"en":"1 point for 5 different responses; 1/2 point for 2.","ar":"درجة واحدة لـ 5 استجابات مختلفة؛ نصف درجة لاستجابتين."}},{"id":"s3-14","level":3,"category":"Social","milestone":14,"text":{"en":"Engages in pretend social play activities with peers for 5 minutes without adult prompts","ar":"ينخرط في أنشطة لعب اجتماعي تخيلي مع الأقران لمدة 5 دقائق دون توجيهات من الكبار"},"objective":{"en":"To determine if the child participates in unscripted, imaginative social play.","ar":"تحديد ما إذا كان الطفل يشارك في لعب اجتماعي تخيلي غير مكتوب."},"application":{"en":"Observe for activities like \"playing house\" or acting out a movie with other children.","ar":"لاحظ الأنشطة مثل \"لعب بيت\" أو تمثيل فيلم مع أطفال آخرين."},"scoring":{"en":"1 point for 5 minutes; 1/2 point for 2 minutes.","ar":"درجة واحدة لـ 5 دقائق؛ نصف درجة لدقيقتين."}},{"id":"s3-15","level":3,"category":"Social","milestone":15,"text":{"en":"Engages in 4 verbal exchanges on 1 topic with peers for 5 topics","ar":"ينخرط في 4 تبادلات لفظية حول موضوع واحد مع الأقران لـ 5 مواضيع"},"objective":{"en":"To determine if the child can maintain a back-and-forth conversation on a single topic.","ar":"تحديد ما إذا كان بإمكان الطفل الحفاظ على محادثة ذهاباً وإياباً حول موضوع واحد."},"application":{"en":"Observe a reciprocal interaction that lasts for at least 4 exchanges, such as discussing making a creek in a sandbox.","ar":"لاحظ تفاعلاً متبادلاً يستمر لـ 4 تبادلات على الأقل، مثل مناقشة إنشاء جدول في صندوق الرمل."},"scoring":{"en":"1 point for 4 exchanges across 5 topics; 1/2 point for 2 exchanges.","ar":"درجة واحدة لـ 4 تبادلات عبر 5 مواضيع؛ نصف درجة لتبادلين."}},{"id":"lr3-11","level":3,"category":"LRFFC","milestone":11,"text":{"en":"Selects correct item from array of 10 with 3 similar stimuli for 25 WH questions","ar":"يختار الشيء الصحيح من مجموعة من 10 مع 3 مثيرات متشابهة لـ 25 سؤال استفهام"},"objective":{"en":"To identify items based on complex verbal descriptions within scenes or the natural environment.","ar":"تحديد الأشياء بناءً على أوصاف لفظية معقدة داخل المشاهد أو البيئة الطبيعية."},"application":{"en":"\"What do you wash with?\" using soap in an array with a small box and mini book.","ar":"\"بماذا تغسل؟\" باستخدام الصابون في مجموعة مع صندوق صغير وكتاب صغير."},"scoring":{"en":"1 point for 25 tasks; 1/2 point for 15.","ar":"درجة واحدة لـ 25 مهمة؛ نصف درجة لـ 15 مهمة."}},{"id":"lr3-12","level":3,"category":"LRFFC","milestone":12,"text":{"en":"Selects from scene/book given 2 verbal components (feature, function, or class)","ar":"يختار من مشهد/كتاب عند إعطائه مكونين لفظيين (ميزة أو وظيفة أو فئة)"},"objective":{"en":"To identify items based on complex verbal descriptions within scenes or the natural environment.","ar":"تحديد الأشياء بناءً على أوصاف لفظية معقدة داخل المشاهد أو البيئة الطبيعية."},"application":{"en":"\"Do you see a brown animal?\" or \"Find clothing with buttons.\"","ar":"\"هل ترى حيواناً بنياً؟\" أو \"ابحث عن ملابس بها أزرار\"."},"scoring":{"en":"1 point for 25 items; 1/2 point for 15.","ar":"درجة واحدة لـ 25 شيئاً؛ نصف درجة لـ 15 شيئاً."}},{"id":"lr3-13","level":3,"category":"LRFFC","milestone":13,"text":{"en":"Selects from scene/book based on 3 verbal components (verb, adj, prep, etc.)","ar":"يختار من مشهد/كتاب بناءً على 3 مكونات لفظية (فعل، صفة، حرف جر، إلخ)"},"objective":{"en":"To identify items based on complex verbal descriptions within scenes or the natural environment.","ar":"تحديد الأشياء بناءً على أوصاف لفظية معقدة داخل المشاهد أو البيئة الطبيعية."},"application":{"en":"\"Which fruit grows on trees?\" or \"Find something round in the sky.\"","ar":"\"أي فاكهة تنمو على الأشجار؟\" أو \"ابحث عن شيء مستدير في السماء\"."},"scoring":{"en":"1 point for 25 items; 1/2 point for 15.","ar":"درجة واحدة لـ 25 شيئاً؛ نصف درجة لـ 15 شيئاً."}},{"id":"lr3-14","level":3,"category":"LRFFC","milestone":14,"text":{"en":"Selects items given 4 rotating questions about a single topic for 25 topics","ar":"يختار الأشياء عند إعطائه 4 أسئلة متناوبة حول موضوع واحد لـ 25 موضوعاً"},"objective":{"en":"To identify items based on complex verbal descriptions within scenes or the natural environment.","ar":"تحديد الأشياء بناءً على أوصاف لفظية معقدة داخل المشاهد أو البيئة الطبيعية."},"application":{"en":"Topic: Cow. Questions: \"Where does it live?\", \"What does it eat?\", etc.","ar":"الموضوع: بقرة. الأسئلة: \"أين تعيش؟\"، \"ماذا تأكل؟\"، إلخ."},"scoring":{"en":"1 point for 25 topics; 1/2 point for 15.","ar":"درجة واحدة لـ 25 موضوعاً؛ نصف درجة لـ 15 موضوعاً."}},{"id":"lr3-15","level":3,"category":"LRFFC","milestone":15,"text":{"en":"Demonstrates 1000 different LRFFC responses","ar":"يظهر 1000 استجابة LRFFC مختلفة"},"objective":{"en":"To identify items based on complex verbal descriptions within scenes or the natural environment.","ar":"تحديد الأشياء بناءً على أوصاف لفظية معقدة داخل المشاهد أو البيئة الطبيعية."},"application":{"en":"Accumulated list of known responses from books or environment.","ar":"قائمة متراكمة من الاستجابات المعروفة من الكتب أو البيئة."},"scoring":{"en":"1 point for 1000 responses; 1/2 point for 750.","ar":"درجة واحدة لـ 1000 استجابة؛ نصف درجة لـ 750 استجابة."}},{"id":"iv3-11","level":3,"category":"Intraverbal","milestone":11,"text":{"en":"Spontaneously emits 20 comments in a single day","ar":"يصدر 20 تعليقاً بشكل عفوي في يوم واحد"},"objective":{"en":"To answer questions about stories, describe past events, and manage rotating WH questions.","ar":"الإجابة على أسئلة حول القصص، ووصف أحداث ماضية، والتعامل مع أسئلة استفهام متناوبة."},"application":{"en":"Responding to \"I'm going to the car\" with \"I want to go for a ride!\".","ar":"الاستجابة لـ \"أنا ذاهب إلى السيارة\" بـ \"أريد الذهاب في جولة!\"."},"scoring":{"en":"1 point for 20 comments; 1/2 point for 10.","ar":"درجة واحدة لـ 20 تعليقاً؛ نصف درجة لـ 10 تعليقات."}},{"id":"iv3-12","level":3,"category":"Intraverbal","milestone":12,"text":{"en":"Demonstrates 300 different intraverbal responses","ar":"يظهر 300 استجابة لفظية داخلية مختلفة"},"objective":{"en":"To answer questions about stories, describe past events, and manage rotating WH questions.","ar":"الإجابة على أسئلة حول القصص، ووصف أحداث ماضية، والتعامل مع أسئلة استفهام متناوبة."},"application":{"en":"Answers varied questions like \"Where does a fish live?\".","ar":"يجيب على أسئلة متنوعة مثل \"أين يعيش السمك؟\"."},"scoring":{"en":"1 point for 300 responses; 1/2 point for 200.","ar":"درجة واحدة لـ 300 استجابة؛ نصف درجة لـ 200 استجابة."}},{"id":"iv3-13","level":3,"category":"Intraverbal","milestone":13,"text":{"en":"Answers 2 questions after being read short passages for 25 passages","ar":"يجيب على سؤالين بعد قراءة فقرات قصيرة لـ 25 فقرة"},"objective":{"en":"To answer questions about stories, describe past events, and manage rotating WH questions.","ar":"الإجابة على أسئلة حول القصص، ووصف أحداث ماضية، والتعامل مع أسئلة استفهام متناوبة."},"application":{"en":"Read a Pooh story and ask \"What was Pooh doing?\".","ar":"اقرأ قصة \"بو\" واسأل \"ماذا كان يفعل بو؟\"."},"scoring":{"en":"1 point for 2 questions (25 passages); 1/2 point for 1 question.","ar":"درجة واحدة لسؤالين (25 فقرة)؛ نصف درجة لسؤال واحد."}},{"id":"iv3-14","level":3,"category":"Intraverbal","milestone":14,"text":{"en":"Describes 25 events/stories with 8 or more words","ar":"يصف 25 حدثاً/قصة بـ 8 كلمات أو أكثر"},"objective":{"en":"To answer questions about stories, describe past events, and manage rotating WH questions.","ar":"الإجابة على أسئلة حول القصص، ووصف أحداث ماضية، والتعامل مع أسئلة استفهام متناوبة."},"application":{"en":"\"Tell me what happened at Grandma's house.\"","ar":"\"أخبرني ماذا حدث في منزل الجدة\"."},"scoring":{"en":"1 point for 25 events (8+ words); 1/2 point for 12 events (5+ words).","ar":"درجة واحدة لـ 25 حدثاً (8+ كلمات)؛ نصف درجة لـ 12 حدثاً (5+ كلمات)."}},{"id":"iv3-15","level":3,"category":"Intraverbal","milestone":15,"text":{"en":"Answers 4 rotating WH questions about a single topic for 10 topics","ar":"يجيب على 4 أسئلة استفهام متناوبة حول موضوع واحد لـ 10 مواضيع"},"objective":{"en":"To answer questions about stories, describe past events, and manage rotating WH questions.","ar":"الإجابة على أسئلة حول القصص، ووصف أحداث ماضية، والتعامل مع أسئلة استفهام متناوبة."},"application":{"en":"Questions about their birthday: \"Where did you go?\", \"What presents did you get?\", etc.","ar":"أسئلة حول عيد ميلادهم: \"أين ذهبت؟\"، \"ما الهدايا التي حصلت عليها؟\"، إلخ."},"scoring":{"en":"1 point for 4 questions (10 topics); 1/2 point for 3 questions (5 topics).","ar":"درجة واحدة لـ 4 أسئلة (10 مواضيع)؛ نصف درجة لـ 3 أسئلة (5 مواضيع)."}},{"id":"cl3-11","level":3,"category":"Classroom","milestone":11,"text":{"en":"Uses the toilet and washes hands with only verbal prompts","ar":"يستخدم المرحاض ويغسل يديه بتوجيهات لفظية فقط"},"objective":{"en":"To assess the child’s ability to follow daily routines, imitate peers, and learn in a group teaching format.","ar":"تقييم قدرة الطفل على اتباع الروتين اليومي، وتقليد الأقران، والتعلم في شكل تدريس جماعي."},"application":{"en":"Provide verbal instructions to use the toilet; observe if the child can sit or stand and wash hands without physical help.","ar":"قدم تعليمات لفظية لاستخدام المرحاض؛ لاحظ ما إذا كان الطفل يستطيع الجلوس أو الوقوف وغسل يديه دون مساعدة جسدية."},"scoring":{"en":"1 point for needing only verbal prompts; 1/2 point if physical assistance is required.","ar":"درجة واحدة للحاجة إلى توجيهات لفظية فقط؛ نصف درجة إذا كانت المساعدة الجسدية مطلوبة."}},{"id":"cl3-12","level":3,"category":"Classroom","milestone":12,"text":{"en":"Responds to 5 different group instructions or questions without direct prompts in a group of 3 or more","ar":"يستجيب لـ 5 تعليمات أو أسئلة جماعية مختلفة دون توجيهات مباشرة في مجموعة من 3 أشخاص أو أكثر"},"objective":{"en":"To assess the child’s ability to follow daily routines, imitate peers, and learn in a group teaching format.","ar":"تقييم قدرة الطفل على اتباع الروتين اليومي، وتقليد الأقران، والتعلم في شكل تدريس جماعي."},"application":{"en":"Observe the child's response to \"group instructions\" that do not include their name, such as \"Everybody stand up\".","ar":"لاحظ استجابة الطفل لـ \"التعليمات الجماعية\" التي لا تتضمن اسمه، مثل \"ليقف الجميع\"."},"scoring":{"en":"1 point for 5 different instructions or questions; 1/2 point for 2.","ar":"درجة واحدة لـ 5 تعليمات أو أسئلة مختلفة؛ نصف درجة لـ 2."}},{"id":"cl3-13","level":3,"category":"Classroom","milestone":13,"text":{"en":"Works independently for 5 minutes in a group and stays on task for 50% of the period","ar":"يعمل بشكل مستقل لمدة 5 دقائق في مجموعة ويبقى في المهمة بنسبة 50% من الفترة"},"objective":{"en":"To assess the child’s ability to follow daily routines, imitate peers, and learn in a group teaching format.","ar":"تقييم قدرة الطفل على اتباع الروتين اليومي، وتقليد الأقران، والتعلم في شكل تدريس جماعي."},"application":{"en":"Observe the child completing an assigned task (e.g., a math worksheet) with only one initial prompt to start.","ar":"لاحظ الطفل وهو يكمل مهمة محددة (مثل ورقة عمل رياضيات) بتوجيه أولي واحد فقط للبدء."},"scoring":{"en":"1 point for 5 minutes at 50% on-task; 1/2 point for 2 minutes at 50%.","ar":"درجة واحدة لمدة 5 دقائق بنسبة 50% في المهمة؛ نصف درجة لمدة دقيقتين بنسبة 50%."}},{"id":"cl3-14","level":3,"category":"Classroom","milestone":14,"text":{"en":"Acquires 2 new behaviors during a 15-minute group-teaching format involving 5 or more children","ar":"يكتسب سلوكين جديدين خلال شكل تدريس جماعي مدته 15 دقيقة يضم 5 أطفال أو أكثر"},"objective":{"en":"To assess the child’s ability to follow daily routines, imitate peers, and learn in a group teaching format.","ar":"تقييم قدرة الطفل على اتباع الروتين اليومي، وتقليد الأقران، والتعلم في شكل تدريس جماعي."},"application":{"en":"Conduct an individual post-test after a group lesson, such as asking a question about a fire safety discussion.","ar":"أجرِ اختباراً بعدياً فردياً بعد درس جماعي، مثل طرح سؤال حول مناقشة السلامة من الحرائق."},"scoring":{"en":"1 point for 2 new behaviors; 1/2 point for 1.","ar":"درجة واحدة لسلوكين جديدين؛ نصف درجة لسلوك واحد."}},{"id":"cl3-15","level":3,"category":"Classroom","milestone":15,"text":{"en":"Sits in a 20-minute group session involving 5 children without disruptive behaviors and answers 5 intraverbal questions","ar":"يجلس في جلسة جماعية مدتها 20 دقيقة تضم 5 أطفال دون سلوكيات تخريبية ويجيب على 5 أسئلة لفظية داخلية"},"objective":{"en":"To assess the child’s ability to follow daily routines, imitate peers, and learn in a group teaching format.","ar":"تقييم قدرة الطفل على اتباع الروتين اليومي، وتقليد الأقران، والتعلم في شكل تدريس جماعي."},"application":{"en":"Observe the child during an academic group activity; they should sit appropriately and participate, such as raising their hand to answer a question.","ar":"لاحظ الطفل أثناء نشاط جماعي أكاديمي؛ يجب أن يجلس بشكل مناسب ويشارك، مثل رفع يده للإجابة على سؤال."},"scoring":{"en":"1 point for sitting appropriately and answering 5 questions; 1/2 point for 2 questions.","ar":"درجة واحدة للجلوس بشكل مناسب والإجابة على 5 أسئلة؛ نصف درجة لسؤالين."}},{"id":"li3-11","level":3,"category":"Linguistics","milestone":11,"text":{"en":"Emits noun inflections (10 plurals and 10 possessions)","ar":"يصدر تصريفات الأسماء (10 جمع و 10 ملكية)"},"objective":{"en":"To assess the use of inflections, complex phrases, and 5-word sentences.","ar":"تقييم استخدام التصريفات والعبارات المعقدة والجمل المكونة من 5 كلمات."},"application":{"en":"\"dogs\" (plural) and \"dog's collar\" (possession).","ar":"\"كلاب\" (جمع) و \"طوق الكلب\" (ملكية)."},"scoring":{"en":"1 point for 10 of each; 1/2 point for 10 of just one category.","ar":"درجة واحدة لـ 10 من كل منهما؛ نصف درجة لـ 10 من فئة واحدة فقط."}},{"id":"li3-12","level":3,"category":"Linguistics","milestone":12,"text":{"en":"Emits verb inflections (10 past tense and 10 future tense)","ar":"يصدر تصريفات الأفعال (10 ماضي و 10 مستقبل)"},"objective":{"en":"To assess the use of inflections, complex phrases, and 5-word sentences.","ar":"تقييم استخدام التصريفات والعبارات المعقدة والجمل المكونة من 5 كلمات."},"application":{"en":"\"I rolled the ball\" and \"We're going to get ice cream.\"","ar":"\"دحرجت الكرة\" و \"سنذهب للحصول على آيس كريم\"."},"scoring":{"en":"1 point for 10 of each; 1/2 point for 10 of just one category.","ar":"درجة واحدة لـ 10 من كل منهما؛ نصف درجة لـ 10 من فئة واحدة فقط."}},{"id":"li3-13","level":3,"category":"Linguistics","milestone":13,"text":{"en":"Emits 10 noun phrases with 3 words and 2 modifiers","ar":"يصدر 10 عبارات اسمية مكونة من 3 كلمات ومعدلين"},"objective":{"en":"To assess the use of inflections, complex phrases, and 5-word sentences.","ar":"تقييم استخدام التصريفات والعبارات المعقدة والجمل المكونة من 5 كلمات."},"application":{"en":"\"He's my puppet\" or \"I want chocolate ice cream.\"","ar":"\"إنه دميتي\" أو \"أريد آيس كريم شوكولاتة\"."},"scoring":{"en":"1 point for 10 phrases; 1/2 point for 5.","ar":"درجة واحدة لـ 10 عبارات؛ نصف درجة لـ 5."}},{"id":"li3-14","level":3,"category":"Linguistics","milestone":14,"text":{"en":"Emits 10 verb phrases with 3 words and 2 modifiers","ar":"يصدر 10 عبارات فعلية مكونة من 3 كلمات ومعدلين"},"objective":{"en":"To assess the use of inflections, complex phrases, and 5-word sentences.","ar":"تقييم استخدام التصريفات والعبارات المعقدة والجمل المكونة من 5 كلمات."},"application":{"en":"\"Push me hard\" or \"Go up the steps.\"","ar":"\"ادفعني بقوة\" أو \"اصعد الدرج\"."},"scoring":{"en":"1 point for 10 phrases; 1/2 point for 5.","ar":"درجة واحدة لـ 10 عبارات؛ نصف درجة لـ 5."}},{"id":"li3-15","level":3,"category":"Linguistics","milestone":15,"text":{"en":"Combines phrases to produce 10 sentences with 5+ words","ar":"يجمع العبارات لإنتاج 10 جمل مكونة من 5 كلمات أو أكثر"},"objective":{"en":"To assess the use of inflections, complex phrases, and 5-word sentences.","ar":"تقييم استخدام التصريفات والعبارات المعقدة والجمل المكونة من 5 كلمات."},"application":{"en":"\"The dog licked my face.\"","ar":"\"الكلب لعق وجهي\"."},"scoring":{"en":"1 point for 10 correct sentences; 1/2 point for 5.","ar":"درجة واحدة لـ 10 جمل صحيحة؛ نصف درجة لـ 5."}},{"id":"r3-11","level":3,"category":"Reading","milestone":11,"text":{"en":"Attends to a book for 75% of the time while a story is read","ar":"ينتبه للكتاب بنسبة 75% من الوقت أثناء قراءة قصة"},"objective":{"en":"To identify early letter knowledge and reading comprehension (matching words to pictures).","ar":"تحديد المعرفة المبكرة بالحروف وفهم القراءة (مطابقة الكلمات بالصور)."},"application":{"en":"Observe if the child looks at pages without being prompted to attend.","ar":"لاحظ ما إذا كان الطفل ينظر إلى الصفحات دون أن يطلب منه الانتباه."},"scoring":{"en":"1 point for 75% of 3 minutes; 1/2 point for 50%.","ar":"درجة واحدة لـ 75% من 3 دقائق؛ نصف درجة لـ 50%."}},{"id":"r3-12","level":3,"category":"Reading","milestone":12,"text":{"en":"Selects correct uppercase letter from array of 5 for 10 letters","ar":"يختار الحرف الكبير الصحيح من مجموعة من 5 لـ 10 حروف"},"objective":{"en":"To identify early letter knowledge and reading comprehension (matching words to pictures).","ar":"تحديد المعرفة المبكرة بالحروف وفهم القراءة (مطابقة الكلمات بالصور)."},"application":{"en":"\"Touch the letter R\" when shown 5 different letters.","ar":"\"المس حرف الراء\" عند عرض 5 حروف مختلفة."},"scoring":{"en":"1 point for 10 letters; 1/2 point for 5.","ar":"درجة واحدة لـ 10 حروف؛ نصف درجة لـ 5 حروف."}},{"id":"r3-13","level":3,"category":"Reading","milestone":13,"text":{"en":"Tacts 10 uppercase letters","ar":"يسمي 10 حروف كبيرة"},"objective":{"en":"To identify early letter knowledge and reading comprehension (matching words to pictures).","ar":"تحديد المعرفة المبكرة بالحروف وفهم القراءة (مطابقة الكلمات بالصور)."},"application":{"en":"Show a letter and ask \"What letter is this?\".","ar":"اعرض حرفاً واسأل \"ما هذا الحرف؟\"."},"scoring":{"en":"1 point for 10 letters; 1/2 point for 5.","ar":"درجة واحدة لـ 10 حروف؛ نصف درجة لـ 5 حروف."}},{"id":"r3-14","level":3,"category":"Reading","milestone":14,"text":{"en":"Reads his own name","ar":"يقرأ اسمه"},"objective":{"en":"To identify early letter knowledge and reading comprehension (matching words to pictures).","ar":"تحديد المعرفة المبكرة بالحروف وفهم القراءة (مطابقة الكلمات بالصور)."},"application":{"en":"Ask \"What does this say?\" while showing their written name with distracters.","ar":"اسأل \"ماذا تقول هذه؟\" أثناء عرض اسمهم المكتوب مع مشتتات."},"scoring":{"en":"1 point for reading name; no 1/2 point.","ar":"درجة واحدة لقراءة الاسم؛ لا توجد نصف درجة."}},{"id":"r3-15","level":3,"category":"Reading","milestone":15,"text":{"en":"Matches 5 words to pictures and vice versa","ar":"يطابق 5 كلمات بالصور والعكس"},"objective":{"en":"To identify early letter knowledge and reading comprehension (matching words to pictures).","ar":"تحديد المعرفة المبكرة بالحروف وفهم القراءة (مطابقة الكلمات بالصور)."},"application":{"en":"Match the written word \"bird\" to a picture of a bird.","ar":"مطابقة الكلمة المكتوبة \"عصفور\" بصورة عصفور."},"scoring":{"en":"1 point for 5 words; 1/2 point for 3.","ar":"درجة واحدة لـ 5 كلمات؛ نصف درجة لـ 3 كلمات."}},{"id":"w3-11","level":3,"category":"Writing","milestone":11,"text":{"en":"Imitates 5 writing actions modeled by an adult","ar":"يقلد 5 حركات كتابة يمثلها شخص بالغ"},"objective":{"en":"To assess fine motor control for tracing, copying letters, and writing one’s name.","ar":"تقييم التحكم الحركي الدقيق للتتبع ونسخ الحروف وكتابة الاسم."},"application":{"en":"Adult draws circles or vertical lines and the child copies.","ar":"يرسم شخص بالغ دوائر أو خطوطاً رأسية ويقوم الطفل بنسخها."},"scoring":{"en":"1 point for 5 actions; 1/2 point for 3.","ar":"درجة واحدة لـ 5 حركات؛ نصف درجة لـ 3 حركات."}},{"id":"w3-12","level":3,"category":"Writing","milestone":12,"text":{"en":"Independently traces within 1/4 inch of 5 geometric shapes","ar":"يتتبع بشكل مستقل في حدود ربع بوصة من 5 أشكال هندسية"},"objective":{"en":"To assess fine motor control for tracing, copying letters, and writing one’s name.","ar":"تقييم التحكم الحركي الدقيق للتتبع ونسخ الحروف وكتابة الاسم."},"application":{"en":"Tracing lines of a circle, star, or triangle.","ar":"تتبع خطوط دائرة أو نجمة أو مثلث."},"scoring":{"en":"1 point for staying within 1/4 inch; 1/2 point for 1/2 inch.","ar":"درجة واحدة للبقاء في حدود ربع بوصة؛ نصف درجة لنصف بوصة."}},{"id":"w3-13","level":3,"category":"Writing","milestone":13,"text":{"en":"Copies 10 letters or numbers legibly","ar":"ينسخ 10 حروف أو أرقام بشكل مقروء"},"objective":{"en":"To assess fine motor control for tracing, copying letters, and writing one’s name.","ar":"تقييم التحكم الحركي الدقيق للتتبع ونسخ الحروف وكتابة الاسم."},"application":{"en":"Child copies A, B, C or 1, 2, 3 from a model.","ar":"ينسخ الطفل أ، ب، ج أو 1، 2، 3 من نموذج."},"scoring":{"en":"1 point for 10 items; 1/2 point for 5.","ar":"درجة واحدة لـ 10 عناصر؛ نصف درجة لـ 5 عناصر."}},{"id":"w3-14","level":3,"category":"Writing","milestone":14,"text":{"en":"Legibly spells and writes name without copying","ar":"يتهجى ويكتب اسمه بشكل مقروء دون نسخ"},"objective":{"en":"To assess fine motor control for tracing, copying letters, and writing one’s name.","ar":"تقييم التحكم الحركي الدقيق للتتبع ونسخ الحروف وكتابة الاسم."},"application":{"en":"Ask the child to write their name on blank paper.","ar":"اطلب من الطفل كتابة اسمه على ورقة بيضاء."},"scoring":{"en":"1 point for legible, correctly spelled name; 1/2 point for approximations.","ar":"درجة واحدة لاسم مقروء ومكتوب بشكل صحيح؛ نصف درجة للتقريبات."}},{"id":"w3-15","level":3,"category":"Writing","milestone":15,"text":{"en":"Copies all 26 letters legibly","ar":"ينسخ جميع الحروف الـ 26 بشكل مقروء"},"objective":{"en":"To assess fine motor control for tracing, copying letters, and writing one’s name.","ar":"تقييم التحكم الحركي الدقيق للتتبع ونسخ الحروف وكتابة الاسم."},"application":{"en":"Child independently copies uppercase and lowercase letters from samples.","ar":"ينسخ الطفل بشكل مستقل الحروف الكبيرة والصغيرة من عينات."},"scoring":{"en":"1 point for all 26 letters; 1/2 point for approximations that aren't clear.","ar":"درجة واحدة لجميع الحروف الـ 26؛ نصف درجة للتقريبات غير الواضحة."}},{"id":"ma3-11","level":3,"category":"Math","milestone":11,"text":{"en":"Identifies numbers 1–5 in an array of 5","ar":"يتعرف على الأرقام 1-5 في مجموعة من 5"},"objective":{"en":"To identify numbers, count with 1:1 correspondence, and match quantity to number.","ar":"التعرف على الأرقام، والعد بمطابقة 1:1، ومطابقة الكمية بالرقم."},"application":{"en":"\"Can you find the number 3?\"","ar":"\"هل يمكنك العثور على الرقم 3؟\"."},"scoring":{"en":"1 point for numbers 1–5; 1/2 point for 1–3.","ar":"درجة واحدة للأرقام 1-5؛ نصف درجة للأرقام 1-3."}},{"id":"ma3-12","level":3,"category":"Math","milestone":12,"text":{"en":"Tacts numbers 1–5","ar":"يسمي الأرقام 1-5"},"objective":{"en":"To identify numbers, count with 1:1 correspondence, and match quantity to number.","ar":"التعرف على الأرقام، والعد بمطابقة 1:1، ومطابقة الكمية بالرقم."},"application":{"en":"Ask \"What number is this?\" for numbers 1–5.","ar":"اسأل \"ما هذا الرقم؟\" للأرقام 1-5."},"scoring":{"en":"1 point for tacting 1–5; 1/2 point for any 3.","ar":"درجة واحدة لتسمية 1-5؛ نصف درجة لأي 3."}},{"id":"ma3-13","level":3,"category":"Math","milestone":13,"text":{"en":"Counts out 1–5 items from a larger set (1:1 correspondence)","ar":"يعد 1-5 عناصر من مجموعة أكبر (مطابقة 1:1)"},"objective":{"en":"To identify numbers, count with 1:1 correspondence, and match quantity to number.","ar":"التعرف على الأرقام، والعد بمطابقة 1:1، ومطابقة الكمية بالرقم."},"application":{"en":"\"Can you get me 3 spoons?\" from a tray of many spoons.","ar":"\"هل يمكنك إحضار 3 ملاعق لي؟\" من صينية بها العديد من الملاعق."},"scoring":{"en":"1 point for counting out 1–5 items; 1/2 point for 1–3 items.","ar":"درجة واحدة لعد 1-5 عناصر؛ نصف درجة لـ 1-3 عناصر."}},{"id":"ma3-14","level":3,"category":"Math","milestone":14,"text":{"en":"Identifies 8 different comparisons involving measurement","ar":"يتعرف على 8 مقارنات مختلفة تتضمن القياس"},"objective":{"en":"To identify numbers, count with 1:1 correspondence, and match quantity to number.","ar":"التعرف على الأرقام، والعد بمطابقة 1:1، ومطابقة الكمية بالرقم."},"application":{"en":"Select \"more/less,\" \"big/little,\" or \"loud/quiet.\"","ar":"اختر \"أكثر/أقل\"، \"كبير/صغير\"، أو \"عالي/هادئ\"."},"scoring":{"en":"1 point for 8 comparisons; 1/2 point for 6.","ar":"درجة واحدة لـ 8 مقارنات؛ نصف درجة لـ 6."}},{"id":"ma3-15","level":3,"category":"Math","milestone":15,"text":{"en":"Matches written number to quantity and vice versa (1–5)","ar":"يطابق الرقم المكتوب بالكمية والعكس (1-5)"},"objective":{"en":"To identify numbers, count with 1:1 correspondence, and match quantity to number.","ar":"التعرف على الأرقام، والعد بمطابقة 1:1، ومطابقة الكمية بالرقم."},"application":{"en":"Match number 3 to a picture of 3 trucks.","ar":"مطابقة الرقم 3 بصورة لـ 3 شاحنات."},"scoring":{"en":"1 point for matching 1–5 in random order; 1/2 point for 1–3.","ar":"درجة واحدة لمطابقة 1-5 بترتيب عشوائي؛ نصف درجة لـ 1-3."}}],"barriers":[{"id":"bar-1","name":{"en":"Negative behaviors (e.g., tantrums, aggression)","ar":"السلوكيات السلبية (مثل نوبات الغضب، العدوانية)"}},{"id":"bar-2","name":{"en":"Poor instructional control (escape and avoidance of demands)","ar":"ضعف التحكم التعليمي (الهروب وتجنب المطالب)"}},{"id":"bar-3","name":{"en":"Absent, weak, or impaired mand repertoire","ar":"غياب أو ضعف أو خلل في حصيلة الطلب"}},{"id":"bar-4","name":{"en":"Absent, weak, or impaired tact repertoire","ar":"غياب أو ضعف أو خلل في حصيلة التسمية"}},{"id":"bar-5","name":{"en":"Absent, weak, or impaired motor imitation","ar":"غياب أو ضعف أو خلل في التقليد الحركي"}},{"id":"bar-6","name":{"en":"Absent, weak, or impaired echoic repertoire","ar":"غياب أو ضعف أو خلل في حصيلة الترديد"}},{"id":"bar-7","name":{"en":"Absent, weak, or impaired visual perceptual skills and matching-to-sample (VP-MTS)","ar":"غياب أو ضعف أو خلل في مهارات الإدراك البصري والمطابقة (VP-MTS)"}},{"id":"bar-8","name":{"en":"Absent, weak, or impaired listener repertoires (LD and LRFFC)","ar":"غياب أو ضعف أو خلل في حصيلة المستمع (LD و LRFFC)"}},{"id":"bar-9","name":{"en":"Absent, weak, or impaired intraverbal repertoire","ar":"غياب أو ضعف أو خلل في حصيلة التواصل اللفظي"}},{"id":"bar-10","name":{"en":"Absent, weak, or impaired social skills","ar":"غياب أو ضعف أو خلل في المهارات الاجتماعية"}},{"id":"bar-11","name":{"en":"Prompt dependent","ar":"الاعتماد على المساعدات"}},{"id":"bar-12","name":{"en":"Scrolling responses (guessing through words)","ar":"الاستجابات العشوائية (التخمين عبر الكلمات)"}},{"id":"bar-13","name":{"en":"Impaired scanning skills","ar":"ضعف مهارات المسح البصري"}},{"id":"bar-14","name":{"en":"Failure to make conditional discriminations (CDs)","ar":"الفشل في إجراء التمييز المشروط (CDs)"}},{"id":"bar-15","name":{"en":"Failure to generalize","ar":"الفشل في التعميم"}},{"id":"bar-16","name":{"en":"Weak or atypical motivating operations (MOs)","ar":"ضعف أو عدم نمطية العمليات الدافعية (MOs)"}},{"id":"bar-17","name":{"en":"Response requirement weakens the MO","ar":"متطلبات الاستجابة تضعف الدافع"}},{"id":"bar-18","name":{"en":"Reinforcement dependent","ar":"الاعتماد على التعزيز"}},{"id":"bar-19","name":{"en":"Self-stimulation","ar":"الاستثارة الذاتية"}},{"id":"bar-20","name":{"en":"Articulation problems","ar":"مشاكل النطق"}},{"id":"bar-21","name":{"en":"Obsessive-compulsive behavior","ar":"السلوك الوسواسي القهري"}},{"id":"bar-22","name":{"en":"Hyperactivity","ar":"النشاط الزائد"}},{"id":"bar-23","name":{"en":"Failure to make eye contact or attend to people","ar":"الفشل في التواصل البصري أو الانتباه للأشخاص"}},{"id":"bar-24","name":{"en":"Sensory defensiveness","ar":"الدفاع الحسي"}}],"barrierGuidance":{"bar-3":{"objective":{"en":"To analyze if a child's ability to request needs is significantly lower than their other verbal skills or if their mands are defective (e.g., prompt bound).","ar":"لتحليل ما إذا كانت قدرة الطفل على طلب الاحتياجات أقل بكثير من مهاراته اللفظية الأخرى أو إذا كانت طلباته معيبة (على سبيل المثال، مقيدة بالتوجيه)."},"scoring":[{"score":1,"en":"Manding is trailing behind Listener Discrimination (LD) and Tact scores.","ar":"الطلب يتأخر عن درجات التمييز السمعي (LD) والتسمية (Tact)."},{"score":2,"en":"Mands are limited to a small set of consumable/tangible reinforcers despite other strong skills.","ar":"تقتصر الطلبات على مجموعة صغيرة من المعززات الاستهلاكية/الملموسة على الرغم من المهارات القوية الأخرى."},{"score":3,"en":"Mands are prompt bound, rote, or involve scrolling.","ar":"الطلبات مقيدة بالتوجيه، أو آلية، أو تتضمن التمرير (scrolling)."},{"score":4,"en":"No functional mands; frequent negative behaviors function as mands.","ar":"لا توجد طلبات وظيفية؛ السلوكيات السلبية المتكررة تعمل كطلبات."}]},"bar-4":{"objective":{"en":"To determine if naming items is out of balance with other skills or if tacts have come under the control of the wrong stimuli (e.g., calling a ball 'throwing ball' without the action).","ar":"لتحديد ما إذا كانت تسمية الأشياء غير متوازنة مع المهارات الأخرى أو إذا كانت التسميات قد خضعت لسيطرة مثيرات خاطئة (على سبيل المثال، تسمية الكرة 'رمي الكرة' بدون الفعل)."},"scoring":[{"score":1,"en":"Tact vocabulary is markedly outnumbered by listener vocabulary.","ar":"مفردات التسمية أقل بكثير من مفردات المستمع."},{"score":2,"en":"Frequent errors, scrolling, or being prompt bound (e.g., requiring lip prompts).","ar":"أخطاء متكررة، أو تمرير، أو التقيد بالتوجيه (على سبيل المثال، طلب توجيهات الشفاه)."},{"score":3,"en":"Fails to generalize, lacks spontaneity, or fails to move beyond single-word tacts.","ar":"يفشل في التعميم، أو يفتقر إلى العفوية، أو يفشل في تجاوز تسميات الكلمة الواحدة."},{"score":4,"en":"Tact repertoire is nonexistent or limited to a few words despite strong echoic skills.","ar":"حصيلة التسمية غير موجودة أو تقتصر على بضع كلمات على الرغم من مهارات الترديد القوية."}]},"bar-5":{"objective":{"en":"To evaluate if a child has difficulty copying the behavior of others, which is the foundation for learning play, social, and self-help skills.","ar":"لتقييم ما إذا كان الطفل يواجه صعوبة في نسخ سلوك الآخرين، وهو الأساس لتعلم مهارات اللعب والمهارات الاجتماعية ومهارات المساعدة الذاتية."},"scoring":[{"score":1,"en":"Acquisition is slower than other milestones; struggles with fine motor or functional imitation.","ar":"الاكتساب أبطأ من المعالم الأخرى؛ يعاني من التقليد الحركي الدقيق أو الوظيفي."},{"score":2,"en":"Difficulty generalizing or copying inappropriate behaviors of others.","ar":"صعوبة في التعميم أو نسخ السلوكيات غير اللائقة للآخرين."},{"score":3,"en":"Imitation is physically or verbally prompt bound ('do this').","ar":"التقليد مقيد بتوجيه جسدي أو لفظي ('افعل هذا')."},{"score":4,"en":"No imitation skills or never uses them spontaneously/functionally.","ar":"لا توجد مهارات تقليد أو لا يستخدمها أبداً بشكل عفوي/وظيفي."}]},"bar-6":{"objective":{"en":"To determine if the inability to repeat words is blocking language development or if the repertoire is too strong (echolalia/scripting).","ar":"لتحديد ما إذا كان عدم القدرة على تكرار الكلمات يعيق تطور اللغة أو إذا كانت الحصيلة قوية جداً (المصاداة/السيناريوهات)."},"scoring":[{"score":2,"en":"Echoically prompt bound; falling behind imitation and matching skills.","ar":"مقيد بتوجيه ترديدي؛ يتأخر عن مهارات التقليد والمطابقة."},{"score":3,"en":"Demonstrates echolalia or delayed echolalia (palilalia); acquisitions are slow and rote.","ar":"يظهر مصاداة أو مصاداة متأخرة (palilalia)؛ الاكتسابات بطيئة وآلية."},{"score":4,"en":"Fails to acquire any echoic behavior despite other listener/imitation skills.","ar":"يفشل في اكتساب أي سلوك ترديدي على الرغم من مهارات المستمع/التقليد الأخرى."}]},"bar-7":{"objective":{"en":"To identify if a child fails to scan arrays, lacks eye-hand coordination, or guesses without discriminating stimuli.","ar":"لتحديد ما إذا كان الطفل يفشل في مسح المصفوفات، أو يفتقر إلى التنسيق بين العين واليد، أو يخمن دون تمييز المثيرات."},"scoring":[{"score":2,"en":"Shows missing elements like failing to scan, position biases, or scrolling.","ar":"يظهر عناصر مفقودة مثل الفشل في المسح، أو انحيازات الموقع، أو التمرير."},{"score":3,"en":"Progress is stalled; child emits escape behavior (tantrums) during matching tasks.","ar":"التقدم متوقف؛ يصدر الطفل سلوك هروب (نوبات غضب) أثناء مهام المطابقة."},{"score":4,"en":"Repertoire is rote or nonexistent; fails to match identical items in the natural environment.","ar":"الحصيلة آلية أو غير موجودة؛ يفشل في مطابقة العناصر المتطابقة في البيئة الطبيعية."}]},"bar-8":{"objective":{"en":"To identify barriers in understanding spoken words, such as failing to attend to speakers or struggling with multiple verbal components.","ar":"لتحديد العوائق في فهم الكلمات المنطوقة، مثل الفشل في الانتباه للمتحدثين أو المعاناة مع المكونات اللفظية المتعددة."},"scoring":[{"score":2,"en":"Side/position biases; responding before the verbal sample is completed.","ar":"انحيازات جانبية/موقعية؛ الاستجابة قبل اكتمال العينة اللفظية."},{"score":3,"en":"Negative behaviors during listener tasks; limited to small arrays; failure to generalize.","ar":"سلوكيات سلبية أثناء مهام المستمع؛ تقتصر على مصفوفات صغيرة؛ الفشل في التعميم."},{"score":4,"en":"No significant listener skills despite other abilities; skills are entirely rote.","ar":"لا توجد مهارات مستمع كبيرة على الرغم من القدرات الأخرى؛ المهارات آلية بالكامل."}]},"bar-9":{"objective":{"en":"To assess difficulty in verbally responding to the words of others, often resulting in rote responses or out-of-context comments.","ar":"لتقييم الصعوبة في الاستجابة اللفظية لكلمات الآخرين، مما يؤدي غالباً إلى استجابات آلية أو تعليقات خارج السياق."},"scoring":[{"score":2,"en":"Frequent errors; scrolling through responses; echolalia; no spontaneous intraverbals.","ar":"أخطاء متمتكررة؛ التمرير عبر الاستجابات؛ المصاداة؛ لا توجد مهارات لفظية تبادلية عفوية."},{"score":3,"en":"Rote responding is persistent; responses are quickly forgotten; no generalization.","ar":"الاستجابة الآلية مستمرة؛ تُنسى الاستجابات بسرعة؛ لا يوجد تعميم."},{"score":4,"en":"Fails to acquire any functional intraverbal behavior despite strong mand and tact skills.","ar":"يفشل في اكتساب أي سلوك لفظي تبادلي وظيفي على الرغم من مهارات الطلب والتسمية القوية."}]},"bar-10":{"objective":{"en":"To evaluate if a child isolates, lacks interest in peers, or exhibits inappropriate social behaviors (e.g., grabbing toys).","ar":"لتقييم ما إذا كان الطفل ينعزل، أو يفتقر إلى الاهتمام بالأقران، أو يظهر سلوكيات اجتماعية غير لائقة (على سبيل المثال، انتزاع الألعاب)."},"scoring":[{"score":2,"en":"Rarely initiates with peers; exhibits socially negative behavior like aggression or grabbing.","ar":"نادراً ما يبادر مع الأقران؛ يظهر سلوكاً سلبياً اجتماعياً مثل العدوانية أو الانتزاع."},{"score":3,"en":"Stays by self; doesn't share or take turns; doesn't respond to peer mands.","ar":"يبقى بمفرده؛ لا يشارك أو يتبادل الأدوار؛ لا يستجيب لطلبات الأقران."},{"score":4,"en":"Actively avoids children; emits negative behavior when forced to interact; no response to peer initiations.","ar":"يتجنب الأطفال بنشاط؛ يصدر سلوكاً سلبياً عند إجباره على التفاعل؛ لا توجد استجابة لمبادرات الأقران."}]}},"barrierGeneric":{"description":{"en":"The VB-MAPP Barriers Assessment is a tool designed to identify and score 24 learning and language acquisition barriers that may impede a child's progress. By identifying these specific obstacles, clinicians can develop targeted intervention strategies to help the child overcome them, ultimately leading to more effective learning.","ar":"تقييم عوائق VB-MAPP هو أداة مصممة لتحديد وتسجيل 24 عائقاً من عوائق التعلم واكتساب اللغة التي قد تعيق تقدم الطفل. من خلال تحديد هذه العقبات المحددة، يمكن للأطباء تطوير استراتيجيات تدخل مستهدفة لمساعدة الطفل على التغلب عليها، مما يؤدي في النهاية إلى تعلم أكثر فعالية."},"scoring":[{"score":0,"en":"No significant barrier exists in that area; no formal intervention is necessary.","ar":"لا يوجد عائق كبير في تلك المنطقة؛ لا يوجد تدخل رسمي ضروري."},{"score":1,"en":"An occasional problem exists that should be monitored, but it may not yet require formal intervention.","ar":"توجد مشكلة عرضية يجب مراقبتها، ولكنها قد لا تتطلب بعد تدخلاً رسمياً."},{"score":2,"en":"A moderate problem exists; further analysis and a potential intervention program should be considered before it worsens.","ar":"توجد مشكلة متوسطة؛ يجب النظر في إجراء مزيد من التحليل وبرنامج تدخل محتمل قبل أن يتفاقم الأمر."},{"score":3,"en":"A persistent problem is present that requires a behavioral analysis and a formal intervention program.","ar":"توجد مشكلة مستمرة تتطلب تحليلاً سلوكياً وبرنامج تدخل رسمي."},{"score":4,"en":"A severe problem exists that significantly disrupts learning and requires an immediate behavioral analysis and formal intervention program.","ar":"توجد مشكلة خطيرة تعطل التعلم بشكل كبير وتتطلب تحليلاً سلوكياً فورياً وبرنامج تدخل رسمي."}]},"transitions":[{"id":"tr-1","category":1,"name":{"en":"Overall VB-MAPP Milestones Score","ar":"إجمالي درجة معالم VB-MAPP"}},{"id":"tr-2","category":1,"name":{"en":"Overall VB-MAPP Barriers Score","ar":"إجمالي درجة عوائق VB-MAPP"}},{"id":"tr-3","category":1,"name":{"en":"Negative Behaviors and Instructional Control","ar":"السلوكيات السلبية والتحكم التعليمي"}},{"id":"tr-4","category":1,"name":{"en":"Classroom Routines and Group Skills","ar":"روتين الفصل ومهارات المجموعة"}},{"id":"tr-5","category":1,"name":{"en":"Social Behavior and Social Play","ar":"السلوك الاجتماعي واللعب الاجتماعي"}},{"id":"tr-6","category":1,"name":{"en":"Independent Work on Academic Tasks","ar":"العمل الأكاديمي المستقل"},"objective":{"en":"To determine if a child can participate in the independent work periods common in less restrictive educational settings, such as completing worksheets or silent reading, without needing constant adult prompting or engaging in disruptive behavior.","ar":"تحديد ما إذا كان بإمكان الطفل المشاركة في فترات العمل المستقل الشائعة في البيئات التعليمية الأقل تقييداً، مثل إكمال أوراق العمل أو القراءة الصامتة، دون الحاجة إلى توجيه مستمر من الكبار أو الانخراط في سلوك تخريبي."},"application":{"en":"The assessor evaluates the child during assigned academic activities to see if they can independently engage in the task and wait for attention or assistance. This is critical because in typical classrooms, teachers rotate between groups and expect students to work without a teacher standing over them.","ar":"يقيم المقيم الطفل أثناء الأنشطة الأكاديمية المحددة لمعرفة ما إذا كان بإمكانه الانخراط بشكل مستقل في المهمة وانتظار الانتباه أو المساعدة. وهذا أمر بالغ الأهمية لأنه في الفصول الدراسية العادية، يتنقل المعلمون بين المجموعات ويتوقعون من الطلاب العمل دون وجود معلم يقف فوقهم."},"scoring":[{"score":1,"en":"The child works independently for at least 30 seconds with only one adult prompt to stay on task.","ar":"يعمل الطفل بشكل مستقل لمدة 30 ثانية على الأقل مع توجيه واحد فقط من الكبار للبقاء في المهمة."},{"score":2,"en":"Intermediate level of increasing time and decreasing prompts.","ar":"مستوى متوسط من زيادة الوقت وتقليل التوجيهات."},{"score":3,"en":"Intermediate level of increasing time and decreasing prompts.","ar":"مستوى متوسط من زيادة الوقت وتقليل التوجيهات."},{"score":4,"en":"The child stays on task for 5 minutes without any adult prompts.","ar":"يبقى الطفل في المهمة لمدة 5 دقائق دون أي توجيهات من الكبار."},{"score":5,"en":"The child is well-prepared for the independent academic activities required in regular education classrooms.","ar":"الطفل مستعد جيداً للأنشطة الأكاديمية المستقلة المطلوبة في فصول التعليم العادي."}]},{"id":"tr-7","category":2,"name":{"en":"Generalization","ar":"التعميم"}},{"id":"tr-8","category":2,"name":{"en":"Variation of Reinforcers","ar":"تنوع المعززات"}},{"id":"tr-9","category":2,"name":{"en":"Rate of Skill Acquisition","ar":"معدل اكتساب المهارات"}},{"id":"tr-10","category":2,"name":{"en":"Retention of New Skills","ar":"الاحتفاظ بالمهارات الجديدة"}},{"id":"tr-11","category":2,"name":{"en":"Learning from the Natural Environment","ar":"التعلم من البيئة الطبيعية"}},{"id":"tr-12","category":2,"name":{"en":"Transfer Without Training","ar":"الانتقال بدون تدريب"}},{"id":"tr-13","category":3,"name":{"en":"Adaptability to Change","ar":"التكيف مع التغيير"}},{"id":"tr-14","category":3,"name":{"en":"Spontaneous Behaviors","ar":"السلوكيات العفوية"}},{"id":"tr-15","category":3,"name":{"en":"Independent Play and Leisure Skills","ar":"اللعب المستقل ومهارات وقت الفراغ"}},{"id":"tr-16","category":3,"name":{"en":"General Self-Help Skills","ar":"مهارات المساعدة الذاتية العامة"}},{"id":"tr-17","category":3,"name":{"en":"Toileting Skills","ar":"مهارات استخدام الحمام"}},{"id":"tr-18","category":3,"name":{"en":"Eating Skills","ar":"مهارات الأكل"}}],"transitionCategories":{"description":{"en":"The VB-MAPP Transition Assessment is designed to identify whether a child is making meaningful progress and has acquired the necessary skills to learn in a less restrictive educational environment. It provides the child’s Individualized Education Program (IEP) team with quantifiable data to help make placement decisions and set educational priorities.","ar":"تم تصميم تقييم انتقال VB-MAPP لتحديد ما إذا كان الطفل يحرز تقدماً ملموساً وقد اكتسب المهارات اللازمة للتعلم في بيئة تعليمية أقل تقييداً. وهو يزود فريق برنامج التعليم الفردي (IEP) الخاص بالطفل ببيانات قابلة للقياس للمساعدة في اتخاذ قرارات التنسيب وتحديد الأولويات التعليمية."},"categories":{"1":{"en":"VB-MAPP Scores and Academic Independence","ar":"درجات VB-MAPP والاستقلال الأكاديمي"},"2":{"en":"Learning Patterns","ar":"أنماط التعلم"},"3":{"en":"Self-Help, Spontaneity, and Self-Direction","ar":"المساعدة الذاتية، العفوية، والتوجيه الذاتي"}},"scoring":{"low":{"en":"Low Scores (0-2): Suggest the child benefits most from a restrictive, high-ratio setting (1:1) with intense behavioral methodology.","ar":"الدرجات المنخفضة (0-2): تشير إلى أن الطفل يستفيد أكثر من بيئة مقيدة ذات نسبة عالية (1:1) مع منهجية سلوكية مكثفة."},"high":{"en":"High Scores (4-5): Suggest the child is likely to be successful in a lower-ratio setting closer to a regular education format.","ar":"الدرجات العالية (4-5): تشير إلى أن الطفل من المرجح أن ينجح في بيئة ذات نسبة أقل أقرب إلى شكل التعليم العادي."}}},"transitionGuidance":{"negative":{"title":{"en":"Negative Behaviors","ar":"السلوكيات السلبية"},"description":{"en":"This section evaluates the degree to which behaviors like whining, crying, tantrums, aggression, or self-injury impede a child's learning.","ar":"يقيم هذا القسم الدرجة التي تعيق بها سلوكيات مثل الأنين أو البكاء أو نوبات الغضب أو العدوانية أو إيذاء النفس تعلم الطفل."},"application":{"en":"Observe the child across various daily situations (denial of items, demands, or periods with low attention) to determine the cause and frequency of these behaviors.","ar":"لاحظ الطفل في مواقف يومية مختلفة (رفض الأشياء، أو المطالب، أو فترات قلة الانتباه) لتحديد سبب وتكرار هذه السلوكيات."},"scoring":[{"score":0,"en":"No significant problem.","ar":"لا توجد مشكلة كبيرة."},{"score":1,"en":"Occasional minor behavior (whining/crying), but the child recovers quickly.","ar":"سلوك بسيط عرضي (أنين/بكاء)، لكن الطفل يتعافى بسرعة."},{"score":2,"en":"Minor behaviors occur daily (refusals, falling to the floor) and are becoming more severe.","ar":"تحدث سلوكيات بسيطة يومياً (رفض، السقوط على الأرض) وتصبح أكثر حدة."},{"score":3,"en":"Persistent problem with more severe behavior (tantrums, throwing things) that is difficult for adults to manage.","ar":"مشكلة مستمرة مع سلوك أكثر حدة (نوبات غضب، رمي الأشياء) يصعب على الكبار إدارتها."},{"score":4,"en":"Severe problem occurring several times a day; behavior is dangerous to self or others (aggression, property destruction).","ar":"مشكلة خطيرة تحدث عدة مرات في اليوم؛ السلوك يشكل خطراً على النفس أو الآخرين (عدوانية، تدمير الممتلكات)."}]},"instructional":{"title":{"en":"Poor Instructional Control","ar":"ضعف التحكم التعليمي"},"description":{"en":"This measures the child's escape and avoidance of demands placed upon them by adults. These behaviors are often controlled by 'conditioned motivating operations-reflexive' (CMO-R), where the demand itself becomes an aversive stimulus the child seeks to remove.","ar":"يقيس هذا هروب الطفل وتجنبه للمطالب التي يضعها عليه الكبار. غالباً ما يتم التحكم في هذه السلوكيات من خلال 'العمليات الدافعية المشروطة-الانعكاسية' (CMO-R)، حيث يصبح الطلب نفسه مثيراً منفراً يسعى الطفل لإزالته."},"application":{"en":"Observe the child's response when asked to complete a task, come to a table, or transition to a less-preferred activity.","ar":"لاحظ استجابة الطفل عند سؤاله لإكمال مهمة، أو المجيء إلى الطاولة، أو الانتقال إلى نشاط أقل تفضيلاً."},"scoring":[{"score":0,"en":"Typically cooperative with adult instructions.","ar":"متعاون عادة مع تعليمات الكبار."},{"score":1,"en":"Minor noncompliance with some demands, but usually cooperative and recovers quickly.","ar":"عدم امتثال بسيط لبعض المطالب، ولكنه متعاون عادة ويتعافى بسرعة."},{"score":2,"en":"Noncompliance occurs a few times a day with minor tantrums; child is difficult to redirect.","ar":"يحدث عدم الامتثال عدة مرات في اليوم مع نوبات غضب بسيطة؛ يصعب إعادة توجيه الطفل."},{"score":3,"en":"Persistent problems; the child emits more severe behavior and avoids a wider range of instructions.","ar":"مشاكل مستمرة؛ يصدر الطفل سلوكاً أكثر حدة ويتجنب مجموعة أوسع من التعليمات."},{"score":4,"en":"Major daily issue; child quickly emits severe behavior (aggression/destruction) if demands are not immediately removed.","ar":"مشكلة يومية كبرى؛ يصدر الطفل سلوكاً حاداً بسرعة (عدوانية/تدمير) إذا لم يتم إزالة المطالب على الفور."}]}},"eesa":[{"id":"eesa-g1-1","group":1,"text":{"en":"ah","ar":"آه"}},{"id":"eesa-g1-2","group":1,"text":{"en":"bye bye","ar":"باي باي"}},{"id":"eesa-g1-3","group":1,"text":{"en":"one","ar":"واحد"}},{"id":"eesa-g1-4","group":1,"text":{"en":"moo","ar":"موو"}},{"id":"eesa-g1-5","group":1,"text":{"en":"we","ar":"نحن"}},{"id":"eesa-g1-6","group":1,"text":{"en":"wow","ar":"واو"}},{"id":"eesa-g1-7","group":1,"text":{"en":"hop","ar":"هوب"}},{"id":"eesa-g1-8","group":1,"text":{"en":"my","ar":"لي"}},{"id":"eesa-g1-9","group":1,"text":{"en":"up","ar":"فوق"}},{"id":"eesa-g1-10","group":1,"text":{"en":"boy","ar":"ولد"}},{"id":"eesa-g1-11","group":1,"text":{"en":"bee","ar":"نحلة"}},{"id":"eesa-g1-12","group":1,"text":{"en":"mama","ar":"ماما"}},{"id":"eesa-g1-13","group":1,"text":{"en":"boo","ar":"بوو"}},{"id":"eesa-g1-14","group":1,"text":{"en":"may","ar":"ماي"}},{"id":"eesa-g1-15","group":1,"text":{"en":"wa wa","ar":"وا وا"}},{"id":"eesa-g1-16","group":1,"text":{"en":"knee","ar":"ركبة"}},{"id":"eesa-g1-17","group":1,"text":{"en":"papa","ar":"بابا"}},{"id":"eesa-g1-18","group":1,"text":{"en":"no no","ar":"لا لا"}},{"id":"eesa-g1-19","group":1,"text":{"en":"pop","ar":"بوب"}},{"id":"eesa-g1-20","group":1,"text":{"en":"toy","ar":"لعبة"}},{"id":"eesa-g1-21","group":1,"text":{"en":"oo","ar":"أوو"}},{"id":"eesa-g1-22","group":1,"text":{"en":"me","ar":"أنا"}},{"id":"eesa-g1-23","group":1,"text":{"en":"oh","ar":"أوه"}},{"id":"eesa-g1-24","group":1,"text":{"en":"too","ar":"أيضاً"}},{"id":"eesa-g1-25","group":1,"text":{"en":"baa","ar":"باع"}},{"id":"eesa-g2-1","group":2,"text":{"en":"baby","ar":"بيبي"}},{"id":"eesa-g2-2","group":2,"text":{"en":"window","ar":"نافذة"}},{"id":"eesa-g2-3","group":2,"text":{"en":"open","ar":"افتح"}},{"id":"eesa-g2-4","group":2,"text":{"en":"taco","ar":"تاكو"}},{"id":"eesa-g2-5","group":2,"text":{"en":"icky","ar":"مقزز"}},{"id":"eesa-g2-6","group":2,"text":{"en":"go eat","ar":"اذهب للأكل"}},{"id":"eesa-g2-7","group":2,"text":{"en":"funny","ar":"مضحك"}},{"id":"eesa-g2-8","group":2,"text":{"en":"oh boy","ar":"يا فتى"}},{"id":"eesa-g2-9","group":2,"text":{"en":"foo-ey","ar":"فوي"}},{"id":"eesa-g2-10","group":2,"text":{"en":"too hot","ar":"ساخن جداً"}},{"id":"eesa-g2-11","group":2,"text":{"en":"nighttime","ar":"وقت الليل"}},{"id":"eesa-g2-12","group":2,"text":{"en":"meow","ar":"مياو"}},{"id":"eesa-g2-13","group":2,"text":{"en":"yumm-o","ar":"يمو"}},{"id":"eesa-g2-14","group":2,"text":{"en":"hankie","ar":"منديل"}},{"id":"eesa-g2-15","group":2,"text":{"en":"monkey","ar":"قرد"}},{"id":"eesa-g2-16","group":2,"text":{"en":"bunny","ar":"أرنب"}},{"id":"eesa-g2-17","group":2,"text":{"en":"kitty","ar":"قطة"}},{"id":"eesa-g2-18","group":2,"text":{"en":"porky","ar":"بوركي"}},{"id":"eesa-g2-19","group":2,"text":{"en":"too bad","ar":"سيء جداً"}},{"id":"eesa-g2-20","group":2,"text":{"en":"uh-oh","ar":"أوه أوه"}},{"id":"eesa-g2-21","group":2,"text":{"en":"my foot","ar":"قدمي"}},{"id":"eesa-g2-22","group":2,"text":{"en":"bow wow","ar":"باو واو"}},{"id":"eesa-g2-23","group":2,"text":{"en":"pay day","ar":"يوم الدفع"}},{"id":"eesa-g2-24","group":2,"text":{"en":"cookie","ar":"كوكيز"}},{"id":"eesa-g2-25","group":2,"text":{"en":"daddy","ar":"بابا"}},{"id":"eesa-g2-26","group":2,"text":{"en":"yucky","ar":"مقزز"}},{"id":"eesa-g2-27","group":2,"text":{"en":"mommy","ar":"ماما"}},{"id":"eesa-g2-28","group":2,"text":{"en":"pokey","ar":"بوكي"}},{"id":"eesa-g2-29","group":2,"text":{"en":"puppy","ar":"جرو"}},{"id":"eesa-g2-30","group":2,"text":{"en":"hot dog","ar":"هوت دوغ"}},{"id":"eesa-g3-1","group":3,"text":{"en":"tubby toy","ar":"لعبة توبي"}},{"id":"eesa-g3-2","group":3,"text":{"en":"potato","ar":"بطاطس"}},{"id":"eesa-g3-3","group":3,"text":{"en":"do high five","ar":"هاي فايف"}},{"id":"eesa-g3-4","group":3,"text":{"en":"tiny pan","ar":"مقلاة صغيرة"}},{"id":"eesa-g3-5","group":3,"text":{"en":"how many","ar":"كم العدد"}},{"id":"eesa-g3-6","group":3,"text":{"en":"banana","ar":"موز"}},{"id":"eesa-g3-7","group":3,"text":{"en":"go bye bye","ar":"اذهب باي باي"}},{"id":"eesa-g3-8","group":3,"text":{"en":"oh foo-ey","ar":"أوه فوي"}},{"id":"eesa-g3-9","group":3,"text":{"en":"peek a boo","ar":"بيك آ بو"}},{"id":"eesa-g3-10","group":3,"text":{"en":"potty time","ar":"وقت الحمام"}},{"id":"eesa-g3-11","group":3,"text":{"en":"fee fi foe","ar":"في فاي فو"}},{"id":"eesa-g3-12","group":3,"text":{"en":"fat doggy","ar":"كلب سمين"}},{"id":"eesa-g3-13","group":3,"text":{"en":"binky boo","ar":"بينكي بو"}},{"id":"eesa-g3-14","group":3,"text":{"en":"teddy bear","ar":"دبدوب"}},{"id":"eesa-g3-15","group":3,"text":{"en":"giddy-up","ar":"هيا انطلق"}},{"id":"eesa-g3-16","group":3,"text":{"en":"yummy food","ar":"طعام لذيذ"}},{"id":"eesa-g3-17","group":3,"text":{"en":"goofy goat","ar":"ماعز غبي"}},{"id":"eesa-g3-18","group":3,"text":{"en":"one cookie","ar":"كوكيز واحدة"}},{"id":"eesa-g3-19","group":3,"text":{"en":"doggy bone","ar":"عظمة الكلب"}},{"id":"eesa-g3-20","group":3,"text":{"en":"wet mitten","ar":"قفاز مبلل"}},{"id":"eesa-g3-21","group":3,"text":{"en":"daddy up","ar":"بابا فوق"}},{"id":"eesa-g3-22","group":3,"text":{"en":"hey me too","ar":"هاي أنا أيضاً"}},{"id":"eesa-g3-23","group":3,"text":{"en":"open up","ar":"افتح"}},{"id":"eesa-g3-24","group":3,"text":{"en":"funny king","ar":"ملك مضحك"}},{"id":"eesa-g3-25","group":3,"text":{"en":"teepee boat","ar":"قارب تيبي"}},{"id":"eesa-g3-26","group":3,"text":{"en":"in a boat","ar":"في القارب"}},{"id":"eesa-g3-27","group":3,"text":{"en":"my big toe","ar":"إصبع قدمي الكبير"}},{"id":"eesa-g3-28","group":3,"text":{"en":"peanut hat","ar":"قبعة الفول السوداني"}},{"id":"eesa-g3-29","group":3,"text":{"en":"a hiccup","ar":"فواق"}},{"id":"eesa-g3-30","group":3,"text":{"en":"puppet game","ar":"لعبة الدمى"}},{"id":"eesa-g4-1","group":4,"text":{"en":"no WAY","ar":"لا يمكن"}},{"id":"eesa-g4-2","group":4,"text":{"en":"ONE bunny","ar":"أرنب واحد"}},{"id":"eesa-g4-3","group":4,"text":{"en":"in a MIN-ute","ar":"في دقيقة"}},{"id":"eesa-g4-4","group":4,"text":{"en":"TAKE it","ar":"خذه"}},{"id":"eesa-g4-5","group":4,"text":{"en":"my MOM-my","ar":"ماما لي"}},{"id":"eesa-g4-6","group":4,"text":{"en":"bug-a-BOO","ar":"بوغ آ بو"}},{"id":"eesa-g4-7","group":4,"text":{"en":"UH-oh","ar":"أوه أوه"}},{"id":"eesa-g4-8","group":4,"text":{"en":"MY mommy","ar":"ماما لي"}},{"id":"eesa-g4-9","group":4,"text":{"en":"bow-WOW","ar":"باو واو"}},{"id":"eesa-g4-10","group":4,"text":{"en":"BUG-a-boo","ar":"بوغ آ بو"}},{"id":"eesa-g5-1","group":5,"text":{"en":"Echoes pitch variations in 1-2 lines of a familiar song","ar":"يردد تنوع النغمات في سطر أو سطرين من أغنية مألوفة"}},{"id":"eesa-g5-2","group":5,"text":{"en":"Echoes continuous warble (fire truck OO-oo-OO-oo-OO)","ar":"يردد صوت صفارة مستمر (سيارة إطفاء)"}},{"id":"eesa-g5-3","group":5,"text":{"en":"Echoes whispering","ar":"يردد الهمس"}},{"id":"eesa-g5-4","group":5,"text":{"en":"Echoes quiet/loud voice (bye-bye vs. BYE-BYE)","ar":"يردد الصوت الهادئ/العالي"}},{"id":"eesa-g5-5","group":5,"text":{"en":"Sustains ahh for 3 seconds, echoically","ar":"يستمر في قول \"آه\" لمدة 3 ثوانٍ ترديدياً"}}],"tasks":[{"id":"ta-m1-1a","milestoneId":"m1-1","text":{"en":"Makes eye contact as a mand for attention","ar":"يتواصل بصرياً كطلب للانتباه"}},{"id":"ta-m1-1b","milestoneId":"m1-1","text":{"en":"Moves close to a reinforcing item","ar":"يتحرك بالقرب من شيء معزز"}},{"id":"ta-m1-1c","milestoneId":"m1-1","text":{"en":"Pulls an adult to get access to a reinforcer","ar":"يسحب شخصاً بالغاً للوصول إلى المعزز"}},{"id":"ta-m1-2a","milestoneId":"m1-2","text":{"en":"Points to 2 different reinforcers","ar":"يشير إلى شيئين معززين مختلفين"}},{"id":"ta-m1-2b","milestoneId":"m1-2","text":{"en":"Nods or says yes/no when offered a reinforcer","ar":"يهز رأسه أو يقول نعم/لا عند عرض معزز"}}],"reference":[{"step":1,"title":{"en":"Conduct the Three Core Assessments","ar":"إجراء التقييمات الأساسية الثلاثة"},"content":{"en":"Before writing goals, you must establish the child's 'operant level' (baseline) across three areas:","ar":"قبل كتابة الأهداف، يجب عليك تحديد 'المستوى الإجرائي' للطفل (خط الأساس) عبر ثلاث مناطق:"},"points":[{"en":"Milestones Assessment: Identifies existing language and related skills across three developmental levels.","ar":"تقييم المعالم: يحدد اللغة الموجودة والمهارات ذات الصلة عبر ثلاثة مستويات تنموية."},{"en":"Barriers Assessment: Identifies 24 learning and language acquisition barriers (e.g., prompt dependency, scrolling, negative behaviors) that may be blocking progress.","ar":"تقييم العوائق: يحدد 24 عائقاً من عوائق التعلم واكتساب اللغة (مثل الاعتماد على التوجيه، التمرير، السلوكيات السلبية) التي قد تعيق التقدم."},{"en":"Transition Assessment: Evaluates 18 measurable areas to determine the child’s readiness for a less restrictive educational environment.","ar":"تقييم الانتقال: يقيم 18 منطقة قابلة للقياس لتحديد مدى استعداد الطفل لبيئة تعليمية أقل تقييداً."}]},{"step":2,"title":{"en":"Determine General Level and Placement","ar":"تحديد المستوى العام والتنسيب"},"content":{"en":"Analyze the Milestone profile to identify the child’s general developmental level (Level 1, 2, or 3).","ar":"تحليل ملف المعالم لتحديد المستوى التنموي العام للطفل (المستوى 1 أو 2 أو 3)."},"points":[{"en":"Level 1 (0–18 months): Focus on the six basic skills: mands, echoics, motor imitation, listener responding (LDs), tacts, and visual perceptual/matching.","ar":"المستوى 1 (0-18 شهراً): التركيز على المهارات الأساسية الست: الطلبات، الترديد، التقليد الحركي، استجابة المستمع (LDs)، التسمية، والإدراك البصري/المطابقة."},{"en":"Level 2 (18–30 months): Expand the size of the mand, tact, and listener repertoires. Introduce LRFFC (Listener Responding by Function, Feature, and Class), intraverbals, and social interactions with peers.","ar":"المستوى 2 (18-30 شهراً): توسيع حجم حصيلة الطلب والتسمية والمستمع. إدخال LRFFC (استجابة المستمع حسب الوظيفة والسمة والفئة)، واللغة التبادلية، والتفاعلات الاجتماعية مع الأقران."},{"en":"Level 3 (30–48 months): Focus on sentence expansion (modifiers), mands for information, intraverbal behavior (talking about things not present), and beginning academics (reading, writing, and math).","ar":"المستوى 3 (30-48 شهراً): التركيز على توسيع الجمل (المعدلات)، وطلبات المعلومات، والسلوك اللفظي التبادلي (التحدث عن أشياء غير موجودة)، وبداية الأكاديميات (القراءة والكتابة والرياضيات)."}]},{"step":3,"title":{"en":"Writing Specific IEP Goals","ar":"كتابة أهداف برنامج التعليم الفردي المحددة"},"content":{"en":"IEP goals should match the identifies milestones and be consistent with the child’s learning history.","ar":"يجب أن تتطابق أهداف برنامج التعليم الفردي مع المعالم المحددة وتكون متسقة مع تاريخ تعلم الطفل."},"points":[{"en":"Time Frame: Goals should typically have a 1-year time frame.","ar":"الإطار الزمني: يجب أن يكون للأهداف عادةً إطار زمني مدته عام واحد."},{"en":"Quantity: The total number of goals should generally be limited to between 12 and 18.","ar":"الكمية: يجب أن يقتصر العدد الإجمالي للأهداف عموماً على ما بين 12 و18 هدفاً."},{"en":"Balance: Priority should be given to bringing the child back into linguistic balance (e.g., if tacts are much lower than listener skills).","ar":"التوازن: يجب إعطاء الأولوية لإعادة الطفل إلى التوازن اللغوي (على سبيل المثال، إذا كانت التسميات أقل بكثير من مهارات المستمع)."},{"en":"Integration of Barriers: The program must include goals to increase skills and goals to decrease barriers.","ar":"تكامل العوائق: يجب أن يتضمن البرنامج أهدافاً لزيادة المهارات وأهدافاً لتقليل العوائق."}]},{"step":4,"title":{"en":"Selecting the Teaching Format","ar":"اختيار تنسيق التدريس"},"content":{"en":"The IEP should specify the teaching strategies that will be most effective for the child:","ar":"يجب أن يحدد برنامج التعليم الفردي استراتيجيات التدريس التي ستكون أكثر فعالية للطفل:"},"points":[{"en":"DTT vs. NET: Level 1 learners often need more structured Discrete Trial Training (DTT), while Level 2 and 3 learners should increase Natural Environment Training (NET).","ar":"DTT مقابل NET: غالباً ما يحتاج متعلمو المستوى 1 إلى تدريب المحاولات المنفصلة (DTT) الأكثر تنظيماً، بينما يجب على متعلمي المستوى 2 و3 زيادة التدريب في البيئة الطبيعية (NET)."},{"en":"Augmentative Communication: Decide whether to implement sign language or a picture system (PECS) if echoic skills are weak.","ar":"التواصل المعزز: قرر ما إذا كنت ستطبق لغة الإشارة أو نظام الصور (PECS) إذا كانت مهارات الترديد ضعيفة."},{"en":"Group Instruction: As a child moves toward Level 2 and 3, goals should focus on learning in a group format.","ar":"التدريس الجماعي: مع انتقال الطفل نحو المستوى 2 و3، يجب أن تركز الأهداف على التعلم في تنسيق جماعي."}]},{"step":5,"title":{"en":"Finalizing with the IEP Team","ar":"اللمسات الأخيرة مع فريق برنامج التعليم الفردي"},"content":{"en":"The results of the VB-MAPP identify what the child needs, but the IEP team must use this data to determine the best interest of the individual child.","ar":"تحدد نتائج VB-MAPP ما يحتاجه الطفل، ولكن يجب على فريق برنامج التعليم الفردي استخدام هذه البيانات لتحديد المصلحة الفضلى للطفل الفردي."},"points":[{"en":"Tailor goals to the child's specific rate of acquisition and available resources.","ar":"تصميم الأهداف وفقاً لمعدل اكتساب الطفل المحدد والموارد المتاحة."},{"en":"Ensure teachers, parents, and professionals are aligned on educational priorities.","ar":"التأكد من توافق المعلمين وأولياء الأمور والمهنيين على الأولويات التعليمية."}]}],"goals":{"Mand-L1":{"en":"Focus on increasing spontaneous mands and reducing prompt dependency.","ar":"التركيز على زيادة الطلبات العفوية وتقليل الاعتماد على المساعدات."},"Tact-L1":{"en":"Develop basic naming skills for common objects and people.","ar":"تطوير مهارات التسمية الأساسية للأشياء والأشخاص المألوفين."},"Barrier-High":{"en":"Prioritize behavior intervention plan to address instructional control issues.","ar":"إعطاء الأولوية لخطة التدخل السلوكي لمعالجة قضايا التحكم التعليمي."}},"additionalGuidance":[{"en":"The assessment results indicate that the child would benefit from an intensive behavioral intervention program. Level 1 milestones suggest a focus on basic manding, tacting, and listener skills in a 1:1 setting.","ar":"تشير نتائج التقييم إلى أن الطفل سيستفيد من برنامج تدخل سلوكي مكثف. تشير معالم المستوى 1 إلى التركيز على مهارات الطلب والتسمية والمستمع الأساسية في بيئة 1:1."},{"en":"Independent Work on Academic Tasks (Transition Item 6)","ar":"العمل المستقل في المهام الأكاديمية (بند الانتقال 6)"},{"en":"To determine if a child can participate in the independent work periods common in less restrictive educational settings, such as completing worksheets or silent reading, without needing constant adult prompting or engaging in disruptive behavior.","ar":"لتحديد ما إذا كان بإمكان الطفل المشاركة في فترات العمل المستقل الشائعة في البيئات التعليمية الأقل تقييداً، مثل إكمال أوراق العمل أو القراءة الصامتة، دون الحاجة إلى حث مستمر من البالغين أو الانخراط في سلوك تخريبي."},{"en":"The assessor evaluates the child during assigned academic activities to see if they can independently engage in the task and wait for attention or assistance. This is critical because in typical classrooms, teachers rotate between groups and expect students to work without a teacher standing over them.","ar":"يقوم المقيم بتقييم الطفل أثناء الأنشطة الأكاديمية المحددة لمعرفة ما إذا كان بإمكانه الانخراط بشكل مستقل في المهمة وانتظار الاهتمام أو المساعدة. هذا أمر بالغ الأهمية لأنه في الفصول الدراسية العادية، يتنقل المعلمون بين المجموعات ويتوقعون من الطلاب العمل دون وقوف المعلم فوقهم."},{"en":"The child works independently for at least 30 seconds with only one adult prompt to stay on task.","ar":"يعمل الطفل بشكل مستقل لمدة 30 ثانية على الأقل مع حث واحد فقط من البالغين للبقاء في المهمة."},{"en":"Intermediate levels of increasing time and decreasing prompts.","ar":"مستويات متوسطة من زيادة الوقت وتقليل الحث."},{"en":"The child works independently for at least 5 minutes with no more than one adult prompt to stay on task.","ar":"يعمل الطفل بشكل مستقل لمدة 5 دقائق على الأقل مع ما لا يزيد عن حث واحد من البالغين للبقاء في المهمة."},{"en":"The child works independently for at least 10 minutes with no adult prompts to stay on task.","ar":"يعمل الطفل بشكل مستقل لمدة 10 دقائق على الأقل دون أي حث من البالغين للبقاء في المهمة."},{"en":"These items focus on barriers that directly interfere with the acquisition of new skills, particularly in the areas of Mand (Requesting), Tact (Labeling), Imitation, Echoic (Vocal Mimicry), and Social Skills.","ar":"تركز هذه البنود على العوائق التي تتداخل مباشرة مع اكتساب مهارات جديدة، لا سيما في مجالات الطلب، التسمية، التقليد، الترديد، والمهارات الاجتماعية."},{"en":"Is the child’s requesting limited, or do they only mand for a few items?","ar":"هل طلبات الطفل محدودة، أم يطلب فقط عدداً قليلاً من العناصر؟"},{"en":"Is the child failing to label common items in their environment?","ar":"هل يفشل الطفل في تسمية العناصر الشائعة في بيئته؟"},{"en":"Does the child struggle to mimic physical actions?","ar":"هل يواجه الطفل صعوبة في تقليد الأفعال الجسدية؟"},{"en":"Does the child have difficulty matching identical objects?","ar":"هل يواجه الطفل صعوبة في مطابقة الأشياء المتطابقة؟"},{"en":"Does the child fail to follow simple instructions?","ar":"هل يفشل الطفل في اتباع التعليمات البسيطة؟"},{"en":"Is the child unable to answer simple questions or complete fill-in-the-blanks?","ar":"هل الطفل غير قادر على الإجابة على أسئلة بسيطة أو إكمال الفراغات؟"},{"en":"Does the child avoid or struggle with peer interactions?","ar":"هل يتجنب الطفل أو يواجه صعوبة في التفاعل مع الأقران؟"},{"en":"Early Echoic Skills Assessment for vocal imitation.","ar":"تقييم مهارات الترديد المبكر للتقليد الصوتي."},{"en":"Track negative behaviors and instructional control.","ar":"تتبع السلوكيات السلبية والتحكم التعليمي."},{"en":"Transition Item 6: Evaluate readiness for independent worksheets or silent reading.","ar":"بند الانتقال 6: تقييم الجاهزية لأوراق العمل المستقلة أو القراءة الصامتة."},{"en":"Detailed analysis of Mand, Tact, Imitation, Echoic, and Social barriers.","ar":"تحليل مفصل لعوائق الطلب، التسمية، التقليد، الترديد، والاجتماعية."},{"en":"The Milestones Assessment identifies existing language and related skills. It is divided into three developmental levels (0-18m, 18-30m, 30-48m).","ar":"يحدد تقييم المعالم اللغة الموجودة والمهارات ذات الصلة. ينقسم إلى ثلاثة مستويات تنموية (0-18 شهر، 18-30 شهر، 30-48 شهر)."},{"en":"Evaluates early echoic skills across five groups of increasing complexity. Based on the EESA subtest of the VB-MAPP.","ar":"يقيم مهارات الترديد المبكر عبر خمس مجموعات تزداد تعقيداً. يعتمد على اختبار EESA الفرعي من VB-MAPP."},{"en":"Evaluate negative behaviors and instructional control to determine educational readiness.","ar":"تقييم السلوكيات السلبية والتحكم التعليمي لتحديد الجاهزية التعليمية."},{"en":"This score is automatically calculated for the Transition Assessment (Category 1, Item 3). A score of 2 or higher in barriers requires a detailed behavioral analysis before academic instruction can be effective.","ar":"يتم حساب هذه الدرجة تلقائياً لتقييم الانتقال (الفئة 1، العنصر 3). تتطلب الدرجة 2 أو أعلى في العوائق تحليلاً سلوكياً مفصلاً قبل أن يكون التدريس الأكاديمي فعالاً."},{"en":"The VB-MAPP provides the quantifiable data necessary for an IEP team to set educational priorities and goals. Follow these detailed clinical steps to build a comprehensive program.","ar":"يوفر VB-MAPP البيانات الكمية اللازمة لفريق برنامج التعليم الفردي لتحديد الأولويات والأهداف التعليمية. اتبع هذه الخطوات السريرية التفصيلية لبناء برنامج شامل."},{"en":"Use the assessment data to generate specific, measurable, and achievable goals for the child.","ar":"استخدم بيانات التقييم لإنشاء أهداف محددة وقابلة للقياس وتحقيقها للطفل."},{"en":"VB-MAPP: Verbal Behavior Milestones Assessment and Placement Program","ar":"VB-MAPP: تقييم معالم السلوك اللفظي وبرنامج التنسيق"},{"en":"Enter detailed clinical summary, behavioral observations, and overall recommendations...","ar":"أدخل ملخصاً إكلينيكياً مفصلاً، ملاحظات سلوكية، وتوصيات عامة..."},{"en":"Based on the comprehensive VB-MAPP assessment results","ar":"بناءً على نتائج تقييم VB-MAPP الشاملة"},{"en":"This report was generated automatically based on the VB-MAPP assessment data.","ar":"تم إنشاء هذا التقرير تلقائياً بناءً على بيانات تقييم VB-MAPP."},{"en":"Based on the current assessment, the child is recommended for a structured environment with a focus on verbal behavior training. Level 1 milestones suggest intensive 1:1 intervention.","ar":"بناءً على التقييم الحالي، يوصى بوضع الطفل في بيئة منظمة مع التركيز على التدريب على السلوك اللفظي. تشير معالم المستوى 1 إلى الحاجة لتدخل مكثف بنسبة 1:1."}],"sourceGaps":{"missingMilestones":["i2-6","i2-7","i2-8","i2-9","i2-10"],"suppliedMilestoneCount":165,"expectedMilestoneCount":170,"suppliedTaskCount":5},"contentReview":{"s2-8":{"en":"The supplied description says 3 minutes, but the supplied full-point criterion says 5 minutes. Verify against your licensed guide before scoring.","ar":"يذكر الوصف المرفق 3 دقائق، بينما يذكر معيار الدرجة الكاملة 5 دقائق. راجع الدليل المعتمد قبل التسجيل."},"tr-6":{"en":"The source contains two different descriptions of the 4- and 5-point criteria for independent work. Both are retained in the reference library. Confirm the criterion in your guide.","ar":"يتضمن المصدر وصفين مختلفين لمعياري الدرجة 4 و5 في العمل المستقل. احتُفظ بكليهما في مكتبة المرجع. تحقّق من المعيار في الدليل."}},"arabicLabels":{"Intraverbal":"الاستجابة اللفظية الحوارية","Echoic":"التقليد الصوتي","Vocal":"السلوك الصوتي التلقائي","Classroom":"مهارات المجموعة وروتين الصف","LRFFC":"استجابة المستمع حسب الوظيفة والصفة والفئة"},"eesaGroups":{"1":{"en":"Simple & reduplicated syllables","ar":"مقاطع بسيطة ومكررة"},"2":{"en":"Two-syllable combinations","ar":"تركيبات من مقطعين"},"3":{"en":"Three-syllable combinations","ar":"تركيبات من ثلاثة مقاطع"},"4":{"en":"Prosody: spoken phrases","ar":"النبر والتنغيم: عبارات منطوقة"},"5":{"en":"Prosody: other contexts","ar":"النبر والتنغيم: سياقات أخرى"}}};
